WITH payload AS (SELECT $archive_payload$[{"id":"38f0b5cc-c8a7-511c-a209-91327da81f2a","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة سيارة -تهديد باستخدام ساح أبيض «سكني» - سلب سيارة -فرار من املوقع -اإلقرار حجة على صاحبه -طلب تشديد العقوبة -التعزير بالسجن واجللد.","document_number":"3433190","case_number":"33686663","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/02/09","year":"1434","subject":"سرقة -سرقة سيارة -تهديد باستخدام ساح أبيض «سكني» - سلب سيارة -فرار من املوقع -اإلقرار حجة على صاحبه -طلب تشديد العقوبة -التعزير بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك ‪ 3433190 :‬تاريخه‪1434/02/09 :‬هـ‬\n                           ‫رقم الدعوى‪33686663:‬‬\n            ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34188755‬تاريخه‪1434/4/15 :‬هـ‬\n\n\n\n      ‫ســرقة ‪ -‬ســرقة ســيارة ‪ -‬تهديــد باســتخدام ســاح أبيــض «ســكني» ‪-‬‬\n      ‫ســلب ســيارة ‪ -‬فــرار مــن املوقــع ‪ -‬اإلقــرار حجــة علــى صاحبــه ‪ -‬طلــب‬\n                            ‫تشــديد العقوبــة ‪ -‬التعزيــر بالســجن واجللــد‪.‬‬\n\n\n\n                          ‫‪1 .1‬القاعدة الفقهية ( اإلقرار حجة على صاحبه )‪.‬‬\n      ‫‪2 .2‬مــا ذكــره أهــل اللغــة أن الســلب يطلــق علــى أخــذ متــاع الغيــر‬\n             ‫ينظــر لســان العــرب (‪ ، )471/1‬املصبــاح املنيــر (‪. )284/1‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام علــى املدعــى عليــه بســلب ســيارة شــخص والفــرار‬\n      ‫بهــا‪ ،‬حيــث تقــدم أحــد الوافديــن إلــى الشــرطة مبلغ ـ ًا عــن قيامــه‬\n      ‫باصطحــاب شــخص مــن احلــراج يف ســيارته مــن نــوع (‪،) ............‬‬\n      ‫إليصالــه إلــى أحــد األحيــاء ‪ ،‬وعنــد دخــول احلــي ‪ ،‬قــام ذلــك الشــخص‬\n      ‫بتهديــده بســاح أبيــض (ســكني)‪ ،‬وإنزالــه مــن ســيارته بالقوة‪،‬والهرب‬\n      ‫بهــا‪ ،‬وبالتعميــم علــى الســيارة‪ ،‬مت القبــض عليهــا‪ ،‬وكانــت بقيــادة‬\n      ‫املدعــى عليــه حينمــا أراد جتــاوز أحــد نقــاط التفتيــش والهــروب ‪ ،‬طلــب‬\n      ‫املدعــي العــام تعزيــر املدعــى عليــه وتشــديد العقوبــة بحقــه لقــاء خطــورة‬\n      ‫مــا أقــدم عليــه مــن جــرم ‪،‬صــادق املدعــى عليــه علــى دعــوى املدعــي‬\n\n‫‪299‬‬\n\f‫العــام ‪ ،‬وحكمــت احملكمــة بتعزيــر املدعــى عليــه بالســجن واجللــد‪،‬‬\n‫قــرر املدعــى عليــه القناعــة مبــا صــدر بحقــه ‪ ،‬كمــا قــرر املدعــي‬\n‫العــام االعتــراض علــى احلكــم بالئحــة الدعــوى ‪ُ ،‬صــدق احلكــم مــن‬\n                                                 ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ .....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بالريــاض برقــم وتاريــخ ‪ 1433/12/01‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم وتاريــخ ‪ 1433/12/01‬ه ـ ففــي يــوم الســبت املوافــق‬\n‫‪1434/01/24‬ه ـ افتتحــت اجللســة الســاعة ‪ 09 : 15‬وفيهــا قــدم املدعــي‬\n‫العــام الئحــة دعــوى عامــة ضــد ‪ 29 .....‬ســنة ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم (‪ ).....‬أوقــف بتاريــخ ‪1433/7/12‬ه ـ مبوجــب أمــر‬\n‫التوقيــف رقــم (‪ )8/6/5853/19‬وتاريــخ ‪1433/7/19‬هــ‪ .‬فبتاريــخ‬\n‫‪1433/7/5‬ه ـ حضــر ملركــز شــرطة‪ .....‬الوافــد ‪ .....‬باكســتاني‬\n‫اجلنســية مبلغــا عــن قيامــه بــإركاب شــخص مــن ‪ ......‬علــى الســيارة التــي‬\n‫كانــت بقيادتــه وهــي مــن نــوع ‪ ........‬رقــم لوحتهــا (‪ ).......‬لغــرض إيصالــه‬\n‫حلــي وعنــد دخولــه احلــي قــام ذلــك الشــخص بتهديــده بســاح أبيــض‬\n‫(ســكني) وإنزالــه مــن الســيارة بالقــوة ومــن ثــم الهــرب بهــا جلهــة غيــر‬\n‫معلومــة‪ .‬وبالبحــث والتحــري عــن الســيارة املوصوفــة أعــاه والتعميــم‬\n‫عنهــا وإشــعار اجلهــات األمنيــة ذات العالقــة ورد كتــاب مديــر شــرطة‬\n‫محافظــة ‪ .......‬رقــم ‪ 32/6/2216/19‬وتاريــخ ‪1433/7/12‬ه ـ املتضمــن‬\n‫أنــه أثنــاء قيــام إحــدى فــرق دوريــات األمــن بعملهــا بنقطــة تفتيــش التابــع‬\n\n                                                                                       ‫‪300‬‬\n\f      ‫للمحافظــة قــام قائــد ســيارة مــن نــوع ‪( .......‬املوصوفــة أعــاه) بتجــاوز‬\n      ‫النقطــة األمنيــة محــاو ًال الهــرب فتــم متابعتــه حتــى القبــض عليــه واتضــح‬\n      ‫أنــه املدعــى عليــه وبعــد االستفســار عــن الســيارة اتضــح أنهــا مســروقة‬\n      ‫ومعمــم عليهــا مــن قبــل مركــز شــرطة ‪ .......‬وبعــرض املدعــى عليــه علــى‬\n      ‫املبلــغ‪ .....‬تعــرف عليــه مــن الوهلــة األولــى وأنــه مــن أخــذ ســيارته منــه‬\n      ‫بالقــوة ‪ .‬وقــد انتهــى التحقيــق إلــى اتهــام املدعــى عليــه بســلب ســيارة‬\n                            ‫املبلــغ والفــرار بهــا‪ .‬وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n                                        ‫‪ -1‬محضر القبض املرفق لفة رقم (‪. )17‬‬\n      ‫‪ -2‬محضــر العــرض املــدون علــى ص (‪ )11‬مــن ملــف التحقيــق املرفــق‬\n                                                                         ‫لفــة رقــم (‪. )1‬‬\n      ‫وببحــث ســوابقه وجــد عليــه ســابقة ترويــج مخــدرات ‪ .‬وحيــث أن مــا‬\n      ‫أقــدم عليــه املذكــور فعــل محــرم ومعاقــب عليــه شــرعا أطلــب إثبــات‬\n      ‫مــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة مشــددة خلطــورة مــا‬\n      ‫أقــدم عليــه مــن جــرم (علمــا بــان احلــق اخلــاص الزال قائمـاً) واهلل املوفــق‬\n      ‫وبعــرض ذلــك علــى املدعــى عليــه أجــاب قائــا الصحيــح أننــي رأيــت‬\n      ‫املبلــغ الباكســتاني واقف ـ ًا بســيارته األجــرة املذكــورة يف وحينمــا نــزل‬\n      ‫منهــا ركبتهــا وهربــت بهــا ومت القبــض علــي كمــا وصــف يف الدعــوى‬\n      ‫هكــذا أجــاب فبنــاء علــى مــا ســلف مــن الدعــوى واإلجابــة وإلقــرار‬\n      ‫املدعــى عليــه بأخــذه الســيارة املذكــورة وهروبــه بهــا وألن الســلب يطلــق‬\n      ‫علــى أخــذ متــاع الغيــر ينظــر لســان العــرب (‪ )471/1‬املصبــاح املنيــر‬\n      ‫(‪ )284/1‬وألن اإلقــرار حجــة علــى صاحبــة وحلرمــة مــا فعلــه املدعى عليه‬\n      ‫وخطورتــه لكونــه مــن االعتــداء علــى أمــوال النــاس واغتصابهــا فقــد‬\n      ‫ثبــت لــدي إدانــة املدعــى عليــه بســلب الســيارة محــل الدعــوى والفــرار‬\n\n\n‫‪301‬‬\n\f‫بهــا وحكمــت عليــه لقــاء ذلــك بســجنه ســنتني تبــدأ مــن تاريــخ اإليقــاف‬\n‫وجلــده أربعمائــة جلــدة مفرقــة علــى ثمــان دفعــات كل دفعــة خمســون‬\n‫جلــدة أمــام النــاس وبــن كل دفعتــن عشــرة أيــام وبعرضــه عليهمــا قــرر‬\n‫املدعــى عليــه القناعــة وقــرر املدعــي العــام االعتــراض مكتفيـ ًا بالئحــة‬\n‫الدعــوى وكان النطــق باحلكــم يف ‪ 1434 / 1 / 24‬ه ـ وأغلقــت اجللســة‬\n‫الســاعة العاشــرة وعليــه جــرى التوقيــع وصلــى اهلل علــى نبينــا محمــد‬\n                                                    ‫وعلــى آلــه وصحبــه وســلم‬\n‫احلمــد هلل وحــده ‪ ...‬وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n‫الرابعــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة مــن‬\n‫فضيلــة رئيــس الـمح ـك ــمة اجل ــزائية بالريــاض برقــم‪ ..........‬وتاريــخ‬\n‫‪1434 /3/9‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي الشــيخ‬\n‫‪ ......‬املســجل برقــم ‪ .......‬وتاريــخ ‪1434/2/9‬ه ـ اخلــاص بدعــوى املدعــي‬\n‫العــام ضــد ‪ .....‬املدعــى عليــه التهامــه بســلب ســيارة علــى النحــو املوضــح‬\n‫بالقــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون بــه‪ ،‬وبدراســة القــرار‬\n‫وصــورة ضبطــه وأوراق املعاملــة قــررت الدائــرة باألكثريــة املصادقــة‬\n‫علــى احلكــم مــع تنبيــه فضيلتــه إلــى ذكــر اســم املدعــي العــام يف أول‬\n‫اجللســة مســتقبالً‪ .‬و اهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                                                ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                     ‫‪302‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":299,"source_page_end":302,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"14f98f559e0b6520866282c287e76016c5a5fbba86f22ac6e6b3485630755e4b","normalized_text_hash":"71963ac937a567f1aef1ada32803fd3a49d5151103a53c122f74556ee02a46db","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p299-3433190"},{"id":"be0b76ba-95ba-57f0-986b-8d77db7f2017","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة سوق وكسر الباب اخلارجي -عدم وجود بينة -رد دعوى املدعي العام .","document_number":"3459049","case_number":"33687118","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف لسماع ما لدى الشهود ومالحظة تصحيح األسماء","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/9","year":"1434","subject":"سرقة -سرقة سوق وكسر الباب اخلارجي -عدم وجود بينة -رد دعوى املدعي العام .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"            ‫رقم الصك ‪ 3459049 :‬تاريخه‪1434/3/9 :‬هـ‬\n                             ‫رقم الدعوى‪33687118 :‬‬\n               ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                     ‫‪ 34219541‬تاريخه‪1434/5/22 :‬هـ‬\n\n\n\n      ‫ســرقة ‪ -‬ســرقة ســوق وكســر البــاب اخلارجــي ‪ -‬عــدم وجــود بينــة ‪ -‬رد‬\n                                                         ‫دعــوى املدعــي العــام ‪.‬‬\n\n\n\n\n      ‫الظـ َّـن َل ُي ْغ ِنــي‬\n                           ‫َك َث ُر ُهـ ْـم ِإ َّل َظ ًّنــا * ِإ َّن َّ‬‫• قــول اهلل تعالــى‪َ { :‬و َمــا َي َّت ِبـ ُـع أ ْ‬\n              ‫ـون} ( يونــس آيــة ‪. )36‬‬         ‫بــا َي ْف َع ُلـ َ‬  ‫الل َع ِليـ ٌـم ِ َ‬‫الـ ِّـق َشـ ْي ًئا * ِإ َّن َّ َ‬\n                                                                                                                       ‫مِ ـ َـن ْ َ‬\n      ‫•حديــث عائشــة رضــي اهلل عنهــا ـ قالــت ‪ :‬قــال رســول اهلل صلــى اهلل‬\n      ‫عليــه وســلم «ادرؤوا احلــدود عــن املســلمني مــا اســتطعتم فــإن كان‬\n      ‫لــه مخــرج فخلــوا ســبيله فــإن اإلمــام أن يخطــئ يف العفــو خيـ ًـرا مــن‬\n                            ‫أن يخطــئ يف العقوبــة» ‪ .‬رواه الترمــذي مرفوعـ ًا ‪.‬‬\n                                         ‫•القاعدة الفقهية ( األصل البراءة ) ‪.‬‬\n                                  ‫•القاعدة الفقهية ( اليقني ال يزول بالشك ) ‪.‬‬\n                        ‫•القاعدة القانونية ( الشك يفسر ملصلحة املُتهم ) ‪.‬‬\n      ‫•قاعــدة ( متــى تطــرق الشــك واالحتمــال إلــى قرائــن األدلــة وجــب‬\n                                                        ‫احلكــم ببــراءة املتهــم ) ‪.‬‬\n\n\n\n\n‫‪303‬‬\n\f‫ادعــى املدعــي العــام علــى املدعــى عليهمــا مبحاولــة كســر البــاب‬\n‫اخلارجــي ألحــد األســواق بقصــد ســرقته‪ ،‬حيــث انتهــى التحقيــق مــن‬\n‫قبــل اجلهــة األمنيــة إلــى توجيــه االتهــام إلــى املدعــى عليهمــا مبحاولــة‬\n‫كســر البــاب اخلارجــي ألحــد األســواق بقصــد الســرقة وطلــب املدعــي‬\n‫العــام تعزيرهمــا لذلــك إال أنــه أنكــر املدعــى عليهمــا مــا جــاء بدعــوى‬\n‫املدعــي العــام‪ ،‬حكمــت احملكمــة بصــرف النظــر عــن دعــوى املدعــى‬\n‫عليهمــا وإخــاء ســبيل املدعــى عليهمــا‪ ،‬عــادت الدعــوى مــن محكمــة‬\n‫االســتئناف لســماع مــا لــدى الشــهود ومالحظــة تصحيــح األســماء‪ ،‬مت‬\n‫طلــب البينــة مــن املدعــي العــام علــى دعــواه ولــم يحضــر فأصــر القاضــي‬\n‫علــى حكمــه الســابق ورفعــت إلــى محكمــة االســتئناف مــرة أخــرى‪،‬‬\n‫عــادت مــن االســتئناف مــرة أخــرى ملالحظــة تغييــر رقــم القــرار ومت‬\n‫اإلجابــة علــى هــذه املالحظــة‪ُ ،‬صــدق احلكــم مــن محكمة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضي يف احملكمــة اجلزائية بخميس‬\n‫مشــيط وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بخميــس مشــيط برقم‪....‬وتاريــخ ‪......‬ه ـ املقيــدة باحملكمــة‬\n‫برقــم ‪ .......‬وتاريــخ ‪ .......‬ه ـ ففــي يــوم األحــد املوافــق ‪ .....‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 11:40‬وفيهــا حضــر املدعــي العــام املكلــف من مرجعه‬\n‫باخلطــاب برقــم ‪ ......‬يف ‪....‬ه ـ وحضــر حلضــوره املدعــى عليــه األول مينــي‬\n‫اجلنســية مبوجــب البطاقــة البديلــة رقــم (‪ ).....‬واملدعــى عليــه الثانــي مينــي‬\n\n                                                                                       ‫‪304‬‬\n\f      ‫اجلنســية مبوجــب البطاقــة البديلــة رقــم (‪ ).....‬وادعــى يف دعــواه احملــررة‬\n      ‫لدينــا انــه انتهــى التحقيــق الــى توجيــه االتهــام للمدعــى عليهمــا مبحاولــة‬\n      ‫كســر البــاب اخلارجــي لســوق ‪ .....‬للمــواد الغذائيــة بقصــد ســرقته وذلــك‬\n      ‫لألدلــة والقرائــن التاليــة ‪1‬ـ مــا جــاء يف تقريــر الدوريــات األمنيــة لفــه (‪)2‬‬\n      ‫‪2‬ـ محضــر االنتقــال واملعاينــة صفحــة (‪ )8‬لفــه رقــم (‪ )1‬وبالبحــث عــن‬\n      ‫ســوابقهما اتضــح عــدم وجــود ســوابق مســجلة عليهما وحيــث أن ما أقدم‬\n      ‫عليــه املذكــوران فعــل محــرم ومعاقــب عليــه شــرعا لــذا أطلــب أثبــات مــا‬\n      ‫أســند إليهمــا واحلكــم عليهمــا بعقوبة تعزيريــة تزجرهما وتردع غيرهما‬\n      ‫هكــذا ادعــى وبســؤال املدعــى عليهمــا عــن الدعــوى اجــاب املدعــى‬\n      ‫عليهمــا كل واحــد منهمــا مبفــرد قائــا مــا ذكــره املدعــي العــام يف‬\n      ‫دعــواه ضدنــا كلــه غيــر صحيــح هكــذا اجابــا وبعــرض إجابــة املدعــى‬\n      ‫عليهمــا علــى املدعــي العــام وســؤاله عــن البينــة علــى صحــة دعــواه أجــاب‬\n      ‫قائــا بينتــي مــا يف أوراق املعاملــة هكــذا أفــاد وبالرجــوع إلــى أوراق‬\n      ‫املعاملــة لــم أجــد أعتــراف أو قرينــة تؤكــد أتهــام املدعــى عليهمــا لــذا‬\n      ‫وبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وبعــد االطــاع علــى املعاملــة‬\n      ‫اخلاصــة بهمــا وبنــاء علــى انــكار املدعــى عليهمــا دعــوى املدعــي العــام‬\n      ‫وحيــث ال بينــة لــدى املدعــي العــام ســوى مــا يف أوراق املعاملــة ومبــا أنــه‬\n      ‫مــن أوراق املعاملــة لــم يتضــح محاولــة املدعــى عليهمــا للســرقه وبنــاء‬\n      ‫علــى ان اليقــن القــوي ال يرتفــع بالشــك الضعيــف والثابــت بيقــن بــراءة‬\n      ‫(((و َمــا َي َّت ِبـ ُـع‬\n                           ‫املتهــم ألنهــا أصــل فــا تــزول براءتــه إال بيقــن ولقولــه تعالــى َ‬\n      ‫بــا‬                    ‫الـ ِّـق َش ـ ْيئًا ِإ َّن َّ َ‬\n            ‫الل َع ِليـ ٌـم ِ َ‬                            ‫الظـ َّـن َل ُي ْغ ِنــي مِ ـ َـن ْ َ‬\n                                                                                             ‫كث َُر ُهـ ْـم ِإ َّل َظ ًّنــا ِإ َّن َّ‬ ‫َأ ْ‬\n      ‫ـون)) وعــن عائشــة رضــي اهلل عنهــا قالــت‪ :‬قــال رســول اهلل صلــى‬                                                    ‫َي ْف َع ُلـ َ‬\n      ‫اهلل عليه وســلم ‪« :‬ادْ َرؤوا احلُدو َد عن املســلمني ما اســتطعتم‪ ،‬فإن كان‬\n\n\n‫‪305‬‬\n\f‫لــه مخــرج‪ ،‬فخلــوا ســبيله‪ .‬فــإن اإلمــام أن يخطــئ يف العفــو‪ ،‬خيــر مــن أن‬\n‫يخطــئ يف العقوبــة» رواه الترمــذي مرفوع ـ ًا والقاعــدة الشــرعية تقــول‬\n‫اليقــن ال يــزول بالشــك واألصــل يف املتهــم البــراءة وبنــاء علــى أنــه متــى‬\n‫تطــرق الشــك واالحتمــال إلــي قرائــن اإلدانــة وجــب احلكــم ببــراءة املتهــم‬\n‫لعــدم كفايــة األدلــة إذ الشــك يفســر ملصلحــة املتهــم وحيــث اليوجــد‬\n‫ســوابق مســجلة علــى املدعــى عليهمــا لذلــك كلــه فقــد رددت دعــوى‬\n‫املدعــى العــام وأخليــت ســبيل املدعــى عليهمــا مــن هــذه الدعــوى هــذا‬\n‫مــا ظهــر لــي وبــه حكمــت وبعــرض احلكــم علــى املدعــى عليهمــا قــرر‬\n‫قناعتهمــا بــه وأمــا املدعــي العــام فقــرر املعارضــة وطلــب رفــع احلكــم‬\n‫لالســتئناف بــدون الئحــة واالكتفــاء بالئحــة الدعــوى لــذا امــرت بتنظيم‬\n‫القــرار الــازم لذلــك ورفــع كامــل أوراق املعاملــة حملكمــة االســتئناف‬\n‫لتدقيــق احلكــم ‪ ..........‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                                        ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‪.....‬‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ .....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بخميــس مشــيط وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة اجلزائيــة بخميــس مشــيط برقــم وتاريــخ ه ـ املقيــدة‬\n‫باحملكمــة برقــم وتاريــخ ه ـ ففــي يــوم الثالثــاء املوافــق ه ـ افتتحــت‬\n‫اجللســة الســاعة العاشــرة وفيهــا حضــر املدعــي العــام املكلــف مــن‬\n‫مرجعــه باخلطــاب برقــم ‪ ......‬يف ‪ ....‬ه ـ وحضــر حلضــوره املدعــى عليهمــا‬\n‫وحيــث قــد عــادت أوراق املعاملــة بخطــاب رئيــس محكمــة االســتئناف‬\n‫برقــم يف ه ـ مشــفوعا بهــا قــرار املالحظــة مــن أصحــاب الفضيلــة قضــاة‬\n‫االســتئناف برقــم يف ه ـ املتضمــن انــه بدراســة القــرار وصــورة ضبطــه‬\n‫وأوراق املعاملــة تقــرر اعادتهــا لفضيلــة حاكمهــا ملالحظــة مايلــي أوال‪/‬‬\n\n\n                                                                                      ‫‪306‬‬\n\f      ‫انــه ورد يف محضــر القبــض وجــود اشــخاص يحاولــون ســرقة احملــل‬\n      ‫‪...‬الــخ فيطلــب شــاهدي محضــر القبــض وأخــذ مــا لديهمــا مــن شــهادة‬\n      ‫بحضــور املدعــى عليهمــا وإجــراء االيجــاب الشــرعي علــى ضــوء ذلــك‪.‬‬\n      ‫ثانيــا‪ /‬تصحيــح االســم االخيــر للمدعــى عليــه الثانــي حســب البطاقــة‬\n      ‫البديلــة املرفقــة لفــة رقــم ‪ 18‬يف القــرار الشــرعي وضبطــه فعلــى فضيلتــه‬\n      ‫مالحظــة ماذكــر واكمــال الــازم واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n      ‫محمــد وعلــى الــه وصحبــه وســلم اه ـ وعليــه وبســؤال املدعــي العــام هــل‬\n      ‫احضــر الشــاهدين افــاد قائــا لــم اســتطع احضارهمــا يف جلســة اليــوم‬\n      ‫وقــدم لنــا صــوره مــن الكتــاب املوجــه الــى ســعادة قائــد دوريــات االمــن‬\n      ‫بخميــس مشــيط برقــم يف ه ـ واملتضمــن طلــب احضــار شــاهدي القبــض‬\n      ‫يف جلســة اليــوم وطلــب املدعــي العــام تأجيــل اجللســة الــى جلســة الحقــة‬\n      ‫ليتمكــن مــن طلــب الشــاهدين مــرة اخــرى فرفعــت اجللســة الســاعة‬\n      ‫العاشــرة والنصــف وحــدد لهــم موعــد يــوم االثنــن املوافــق ه ـ العاشــره‬\n      ‫والنصــف ‪ ..........‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                                   ‫آلــه وصحبــه وســلم‪ .‬حــرر يف ‪.....‬‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....................‬القاضــي يف احملكمــة‬\n      ‫اجلزائيــة بخميــس مشــيط وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة اجلزائيــة بخميــس مشــيط برقــم وتاريــخ ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم وتاريــخ ه ـ ففــي يــوم اإلثنــن املوافق‪1434/03/02‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة العاشــرة والنصــف وفيهــا حضــر املدعــي‬\n      ‫العــام واملدعــى عليهمــا وبســؤال املدعــي العــام هــل احضــر مــا اســتمهل‬\n      ‫مــن اجلــه أفــاد قائــا ال وأطلــب إعطائــي مهلــة أخــرى إلــى يــوم االثنــن‬\n      ‫املوافــق ه ـ ولطلــب املدعــى العــام رفعــت اجللســة الــى يــوم االثنــن املوافــق‬\n\n\n‫‪307‬‬\n\f‫الســاعة العاشــرة والنصــف ‪ ..........‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n                     ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪.....‬‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم اإلثنــن املوافــق افتتحــت اجللســة‬\n‫الســاعة العاشــرة والنصــف وفيهــا حضــر املدعــي العــام واملدعــى عليهمــا‬\n‫وبســؤال املدعــي العــام هــل أحضــر شــاهدي القبــض افــاد قائــا انــه مت‬\n‫مخاطبــة ســعادة قائــد الدوريــات األمنيــة بخميــس مشــيط باخلطــاب رقــم‬\n‫يف ه ـ بطلــب حضــور الشــاهدين اال انهمــا لــم يحضــرا وانــا عاجــز عــن‬\n‫احضارهمــا ومت ارفــاق صــورة مــن اخلطــاب باملعاملــه كمــا افــاد انــه‬\n‫ليــس لــدي بينــة ســوى مــايف اوراق املعاملــة هكــذا افــاد كمــا جــرى‬\n‫تصحيــح اســم املدعــى عليــه مبــا يوافــق البطاقــة البديلــة لــذا ومبــا ان‬\n‫املدعــي العــام ليــس لديــه بينــة ولــم يســتطع احضــار شــاهدي القبــض‬\n‫ومت تأجيــل اجللســة اكثــر مــن مــرة لــذا ال زلــت علــى حكمــي الســابق‬\n‫وامــرت باحلــاق ذلــك واعــادة كامــل اوراق املعاملــة حملكمــة االســتئناف‬\n‫لتدقيــق احلكــم وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى الــه‬\n                                                    ‫وصحبــه وســلم حــرر يف‪.....‬‬\n‫احلمــد هلل وحــده وبعــد وحيــث قــد عــادت أوراق املعاملــة بخطــاب رئيــس‬\n‫محكمــة االســتئناف املكلــف مبنطقــة عســير برقــم يف ه ـ مشــفوعا‬\n‫بهــا قــرار املالحظــة مــن أصحــاب الفضيلــة قضــاة االســتئناف بالدائــرة‬\n‫الثالثــة برقــم يف ه ـ املتضمــن انــه بدراســة القــرار وصــورة ضبطه وأوراق‬\n‫املعاملــة وباالطــاع علــى مــا اجــاب بــه فضيلتــه بنــاء علــى قرارنــا رقــم‬\n‫(‪ ).....‬وتاريــخ ‪ ...‬ه ـ تقــرر اعادتهــا لفضيلــة حاكمهــا ملالحظــة ان القــرار‬\n‫املرفــق باملعاملــة للتدقيــق ال يطابــق رقــم القــرار الســابق دراســته مــن‬\n‫قبلنــا فعلــى فضيلتــه مالحظــة مــا ذكــر وإكمــال الــازم واهلل املوفــق‬\n\n\n                                                                                    ‫‪308‬‬\n\f      ‫وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم أه ـ وعليه جنيب‬\n      ‫اصحاب الفضيلة قضاة االســتئناف حفظهم اهلل انه بناء على امللحوظة‬\n      ‫الثانيــة يف القــرار الســابق واملتضمــن تصحيــح اســم املدعــى عليــه الثانــي‬\n      ‫االخيــر جــرى تعديــل االســم واضافــة جلســات وطباعــة القــرار الشــرعي‬\n      ‫مــرة اخــرى‪ ،‬وبالكتابــة إلــى رئيــس قســم احلاســب االلــى باحملكمــة‬\n      ‫لالفــادة عــن ســبب تغييــر رقــم القــرار عــن القــرار الســابق فافــاد كمــا‬\n      ‫هــو موضــح يف اوراق املعاملــة بكتابــه رقــم يف ه ـ املتضمــن انــه يف حالــة‬\n      ‫التعديــل واإلضافــة يتــم تغييــر رقــم القــرار تلقائيــا وللبيــان جــرى إحلــاق‬\n      ‫ذلــك وأمــرت بإعــادة كامــل أوراق املعاملــة لالســتئناف لتدقيــق احلكــم‬\n                            ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد حــرر يف ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثالثــة لتدقيــق‬\n      ‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بخميــس مشــيط برقم‪.....‬‬\n      ‫وتاريــخ ‪ .....‬املرفــق بهــا القــرار الصــادر مــن فضيل ــة القاضــي باحملكمــة‬\n      ‫الشيخ ‪ ...........‬برقم وتاريخ هـ اخلاص بدعوى املدعي العام ض ـ ــد كل‬\n      ‫مــن‪ ...........‬و ‪- ..........‬مينيـ ّـي اجلنســية‪ -‬يف قضيــة (محاولــة كســر أحــد‬\n      ‫أبــواب احملــات وســرقة مــا بداخلهــا) علــى الصفــة املوضحــة يف القــرار‬\n      ‫املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه وحيــث ســبق‬\n      ‫دراســة القــرار وصــورة ضبطــه وأوراق املعاملــة وباالطــاع علــى مــا أجــاب‬\n      ‫ـاء علــى قرارنــا رقــم (‪).....‬‬\n                                   ‫بــه فضيلتــه وأحلقــه بالقــرار وصــورة ضبطــه بنـ ً‬\n      ‫وتاريــخ ‪1434/4/10‬ه ـ ‪ .‬تقــررت املوافقــة علــى احلكــم بعــد اإليضــاح‬\n      ‫األخيــر واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n‫‪309‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":303,"source_page_end":309,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"70a1d20cab4b49b166fbcf8a1196fbbede5a382a83a6276348807512234c53fb","normalized_text_hash":"afc6027f8c8ae9a8865d8ffaa7c87185d7a1426011e78ab3535fef3d2aef0305","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p303-3459049"},{"id":"562864d7-b0d9-5dd4-a733-39d38e92c67f","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -تزوير -تقدمي شيك مزور -استيالء على سبائك ذهب -تستر على اجلناة -خيانة األمانة -إقرار املدعى عليهم -املبدأ القضائي بتضمن املختلسن -التعزير بالسجن واجللد .","document_number":"34266892","case_number":"33694683","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/07/12","year":"1434","subject":"سرقة -تزوير -تقدمي شيك مزور -استيالء على سبائك ذهب -تستر على اجلناة -خيانة األمانة -إقرار املدعى عليهم -املبدأ القضائي بتضمن املختلسن -التعزير بالسجن واجللد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34266892 :‬تاريخه‪1434/07/12 :‬هـ‬\n                     ‫رقم الدعوى‪33694683 :‬‬\n      ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34347482‬تاريخه‪1434/11/3 :‬هـ‬\n\n\n\n ‫ســرقة ‪ -‬تزويــر ‪ -‬تقــدمي شــيك مــزور ‪ -‬اســتيالء علــى ســبائك ذهــب‬\n ‫‪ -‬تســتر علــى اجلنــاة ‪ -‬خيانــة األمانــة ‪ -‬إقــرار املدعــى عليهــم ‪ -‬املبــدأ‬\n           ‫القضائــي بتضمــن املختلســن ‪ -‬التعزيــر بالســجن واجللــد ‪.‬‬\n\n\n\n\n ‫ا عــن ابــن رشــد‪ (:‬إذا اجتمــع‬\n                                ‫‪ -‬مــا جــاء يف مواهــب اجلليــل (‪ )316/6‬نقـ ً‬\n ‫القــوم يف الغصــب‪ ،‬أو الســرقة‪ ،‬أو احلرابــة‪ ،‬فــكل واحــد منهــم ضامــن‬\n ‫جلميــع مــا أخــذوه‪ ،‬ألن بعضهــم قــوي ببعــض ‪ ،‬كالقــوم يجتمعــون‬\n      ‫علــى قتــل رجــل‪ ،‬فيقتــل جميعهــم بــه ‪ ،‬وإن ولــي القتــل أحدهــم )‪.‬‬\n ‫‪ -‬قــرار مجلــس القضــاء األعلــى رقــم ‪ 3/199‬يف ‪1421/03/04‬ه ـ‬\n ‫املتضمــن‪ :‬مبــد ًأ قضائيـ ًا يتعلــق بتضمــن املختلســن ‪(.‬ينظــر ‪ :‬مدونــه‬\n                     ‫اإلحــكام القضائيــة ‪ ،‬اإلصــدار األول (‪ 1428‬ص ‪.)6‬‬\n\n\n\n\n ‫ادعــى املدعــي العــام علــى املدعــى عليهــم األول بتقــدمي شــيك مــزور ألحــد‬\n ‫املؤسســات ‪ ،‬وتســتره علــى اجلنــاة الهاربــن ‪ ،‬والثانــي بحيــازة وبيــع عــدد‬\n ‫أربــع ســبائك ذهــب اتضــح أنهــا مــن نفــس الســبائك التــي قــام األول‬\n ‫بشــرائها ‪ ،‬والثالــث بخيانــة األمانــة ‪ ،‬حيــث تقدم أحد األشــخاص ببالغ‬\n ‫للشــرطة عــن ســحب مبلــغ وقــدره مليونــان وســت مائــة وأربعــة تســعون‬\n                                                                                     ‫‪310‬‬\n\f      ‫ألــف ريــال (‪ ،)2.694.000‬مــن حســاب شــركته ‪،‬وعنــد مراجعــة‬\n      ‫املصــرف ‪ ،‬تفاجــأ أن املبلــغ ســحب بشــيك لصالــح محــل الذهــب‪ ،‬وأن‬\n      ‫مــن قــام بتقــدمي الشــيك هــو املدعــى عليــه األول ‪ ،‬ومبشــاهدة الشــيك‬\n      ‫تبــن أنــه كتــب بخــط ‪ ،‬يشــبه خــط املدعــى عليــه الثالــث ‪ ،‬والــذي‬\n      ‫يعمــل مبؤسســة املدعــي ‪ ،‬كمــا توفــرت معلومــات لــدى اجلهــات األمنيــة‬\n      ‫بــأن هنــاك شــخص حــاول بيــع ســبائك ذهبيــة ‪ ،‬التــي مت شــراءها مــن‬\n      ‫املؤسســة التــي صــدر باســمها الشــيك املــزور ‪ ،‬ومت القبــض عليــه ‪،‬‬\n      ‫وتبــن أنــه املدعــى عليــه الثانــي ‪ ،‬وطلــب املدعــي العــام تعزيرهــم لقــاء‬\n      ‫مــا نســب إليهــم ‪ ،‬أقــر املدعــى عليهمــا األول والثانــي مبــا جــاء بدعــوى‬\n      ‫املدعــي العــام ‪ ،‬وأنكــر املدعــى عليــه الثالــث الدعــوى ‪ ،‬حضــر املدعــي‬\n      ‫اخلــاص وطلــب تضمــن املدعــى عليهــم الثالثــة قيمــة الشــيك املــزور ‪،‬‬\n      ‫أنكــر املدعــى عليهــم مبــا جــاء بدعــوى املدعــي اخلــاص ‪ ،‬جــرى االطــاع‬\n      ‫علــى أوراق املعاملــة ومــن ضمنهــا التقريــر الفنــي الصــادر مــن شــعبة‬\n      ‫الفحــوص باألدلــة اجلنائيــة املتضمــن أن اخلــط والتوقيــع منســوخ كليـاً‪،‬‬\n      ‫ومبضاهاتــه اتضــح أنــه مطابــق خلــط املدعــى عليــه الثالــث ‪ ،‬احلكــم‬\n      ‫بتعزيــر املدعــى عليهــم األول والثانــي والثالــث بالســجن واجللــد لقــاء‬\n      ‫احلــق العــام ‪ ،‬احلكــم بإلــزام املدعــى عليــه األول والثانــي متضامنــن‬\n      ‫بإعــادة مبلــغ الشــيك املــزور ال يبــرأ أحدهمــا إال بســداد املبلــغ كامـاً‪،‬‬\n      ‫احلكــم بــرد دعــوى املدعــي اخلــاص ضــد املدعــى عليــه الثالــث لعــدم‬\n      ‫كفايــة األدلــة ‪ ،‬قــرر املدعــى عليهــم اعتراضهــم علــى احلكــم بالئحــة‬\n      ‫اعتراضيــة واملدعــي اخلــاص اعتراضــه على احلكــم بالئحة اعتراضية‪،‬‬\n      ‫واملدعــي العــام اعتراضــه علــى احلكــم بــدون الئحــة ‪ ،‬صــدق احلكــم‬\n                                                       ‫مــن محكمــة االســتئناف‪.‬‬\n\n\n‫‪311‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنا‪.....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بالريــاض برقــم وتاريــخ ‪ 1433/12/20‬ه ـ املقيــدة باحملكمــة‬\n‫برقم وتاريخ ‪ 1433/12/20‬هـ ففي يوم األحد املوافق‪1434/01/11‬هـ‬\n‫افتتحــت اجللســة الســاعة ‪ 12 : 15‬وفيهــا قــدم املدعــي العــام ‪ .....‬بصفتي‬\n      ‫عضــو هيئــة التحقيــق واالدعــاء العــام مبدينــة الريــاض ادعــي علــى‪:‬‬\n‫‪1‬ـ ‪ .......‬مينــي اجلنســية مبوجــب رخصة اإلقامــة رقم(‪،).........‬أوقف بتاريخ‬\n‫‪1432/10/21‬ه ـ واطلــق ســراحه بتاريــخ ‪1432/12/28‬ه ـ واعيــد‬\n‫للتوقيــف بتاريــخ ‪1433/3/5‬ه ـ وأحيــل لشــعبة ســجن امللــز مبوجــب‬\n‫مذكــرة التوقيــف رقــم(‪ )15/6/596/2‬وتاريــخ ‪1433/5/15‬ه ـ‬\n‫اســتنادا للقــرار الــوزاري رقــم(‪ )1900‬املبنــي علــى املــادة رقــم (‪ )112‬مــن‬\n                                                  ‫نظــام اإلجــراءات اجلزائيــة‪.‬‬\n‫‪2‬ـ ‪ .........‬مينــي اجلنســية مبوجــب رخصــة اإلقامــة رقم(‪)..........‬أوقــف‬\n‫بتاريخ‪1432/9/23‬ه ـ واطلــق ســراحه بتاريــخ ‪1432/9/28‬ه ـ واعيــد‬\n‫للتوقيــف بتاريــخ ‪1433/6/16‬ه ـ وأحيــل لشــعبة ســجن امللــز مبوجــب‬\n‫مذكــرة التوقيــف رقــم (‪ ).....‬وتاريخ‪1433/6/28‬ه ـ اســتنادا للقــرار‬\n‫الــوزاري رقــم(‪ )1900‬املبنــي علــى املــادة رقم (‪ )112‬من نظــام اإلجراءات‬\n                                                                 ‫اجلزائيــة‪.‬‬\n‫‪3‬ـ ‪ ..........‬مصــري اجلنســية مبوجــب رخصــة اإلقامــة رقم(‪،).......‬أوقــف‬\n‫بتاريخ‪1432/9/23‬ه ـ واطلــق ســراحه بتاريــخ ‪1432/9/27‬ه ـ وأعيــد‬\n‫للتوقيــف بتاريــخ ‪1433/5/14‬ه ـ وأحيــل لشــعبة ســجن امللــز مبوجــب‬\n\n                                                                                    ‫‪312‬‬\n\f      ‫مذكــرة التوقيــف رقم(‪)15/6/610/2‬وتاريخ‪1433/6/28‬ه ـ اســتنادا‬\n      ‫للقــرار الــوزاري رقــم(‪ )1900‬املبنــي علــى املــادة رقــم (‪ )112‬مــن نظــام‬\n                                                                 ‫اإلجــراءات اجلزائيــة‪.‬‬\n      ‫بتاريــخ ‪1432/9/23‬ه ـ تقــدم املواطــن‪ .....‬ببــاغ ملركــز شــرطة‬\n      ‫الســليمانية عــن ســحب مبلــغ مليونــان وســت مائــه وأربعــه وتســعون ألــف‬\n      ‫(‪ )2.694.000‬ريــال مــن حســاب الشــركة العائــدة لــه (شــركة ‪).....‬‬\n      ‫وعنــد مراجعتــه للبنــك تفاجــأ بــأن املبلــغ ســحب بالشــيك رقــم (‪)796‬‬\n      ‫مــن فــرع مصــرف ‪ .....‬بحــي ‪ .....‬لصالــح محــل للذهــب وتبــن ان مــن‬\n      ‫قــام بتقــدمي الشــيك ملؤسســة هــو‪ .....‬املدعــى عليــه األول ‪ ،‬وأضــاف‬\n      ‫أنــه عنــد مراجعتــه للبنــك ومشــاهدته للشــيك الــذي مت مبوجبــه صــرف‬\n      ‫املبلــغ تبــن انــه غيــر صحيــح ومــزور (جــرى فــرز اوراق مســتقلة لقضيــة‬\n      ‫التزويــر)وان اخلــط املــدون مشــابه حلــد كبيــر خلــط املوظــف‪ .......‬مصــري‬\n      ‫اجلنســية الــذي يعمــل لديــه محاســب يف الشــركة ‪ -‬فجــرى اتخــاذ جملــة‬\n      ‫مــن االجــراءات البحثيــة التــي متثلــت يف طلــب الشــيك الــذي مت مبوجبــه‬\n      ‫صــرف املبلــغ محــل الدعــوى وقــد جــرى اســتدعاء املتهــم (املدعــى عليــه‬\n      ‫الثالــث) وإيقافــه باملركــز‪ ،‬ثــم وردهــم كتــاب إدارة التحريــات‬\n      ‫والبحــث اجلنائــي رقــم يف ‪1433/9/27‬ه ـ املتضمــن القبــض علــى‬\n      ‫كمــا توفــرت معلومــات بــان هنــاك شــخص حــاول بيــع بعــض الســبائك‬\n      ‫الذهبيــة التــي مت شــراءها مــن محــل بالشــيك املــزور ومت القبــض عليــه‬\n                     ‫وتبــن انه(املدعــى عليــه الثانــي ) ومت إيقافــه باملركــز ‪.‬‬\n      ‫وقــد اثبــت التقريــر الفنــي رقــم (‪)......‬الصــادر مــن شــعبة الفحــوص‬\n      ‫الفنيــة للتزييــف والتزويــر بــإدارة األدلــة اجلنائيــة املتضمــن بــان الشــيك‬\n      ‫واخلــط املــدون عليــه منســوخ كليـ ًا مبــا فيــه اخلــط والتوقيــع ومبضاهــات‬\n\n\n‫‪313‬‬\n\f‫اخلــط املوجــود علــى الشــيك اتضــح بانــه مطابــق خلــط املتهــم‪ .........‬بضبط‬\n‫افــادة ‪ .....‬ســعودي اجلنســية هويــة رقــم(‪ ).........‬يعمــل يف مكتــب للذهــب‬\n‫واملجوهــرات الــذي افــاد بأنــه يف يــوم االثنــن املوافق‪1432/9/20‬ه ـ‬\n‫تلقــى اتصــال عــن طريــق هاتــف احملــل مــن شــخص ادعــى بأنــه منــدوب‬\n‫شــركة ‪ .....‬وانــه يرغــب يف شــراء اثنــان كيلــو ذهــب عيــار‪ 24‬وأنــه‬\n‫ســوف يقــوم بإرســال مندوبــه ويدعــى‪ ....... /‬ومعــه شــيك وتفويــض‬\n‫وبعــد حضــور املنــدوب مت صــرف الشــيك يف بنــك ‪ .....‬وايــداع كامــل‬\n‫املبلــغ يف حســاب مؤسســة تلقــى اتصــال مــن شــركة ‪ .....‬يفيــد بــان‬\n‫الشــيك مــزور فتــم تدويــن أرقــام ســبايك الذهــب والتعميــم عليهــا لــدى‬\n‫محــات الذهــب واملجوهــرات وبضبــط إفــادة‪ /‬ســوداني اجلنســية إقامــة‬\n‫رقــم(‪ )...........‬يعمــل يف مكتــب للذهــب الــذي أفــاد أنــه بعــد حضــور‬\n‫منــدوب شــركة ‪ .....‬املدعــو‪ /‬وقــام بتســليم الشــيك واســتالم ســبائك‬\n‫الذهــب قــام مبرافقتــه خلــارج احملــل وطلبــه منــه توصيلــه الــى ســيارته‬\n‫فرفــض املنــدوب ذلــك وأفــاد بــأن الســيارة قريبــة وبعــد ذلــك توجــه للبنــك‬\n‫لصــرف الشــيك وبســؤاله عــن قيــام مجموعــة اشــخاص بخطــف‪ /‬امــام‬\n‫محــل الذهــب أفــاد بأنــه لــم يــرى أحــد قــام باختطافــه وانــه غــادر احملــل‬\n‫بــدون ان يالحــظ عليــه أي شــيء وباســتجواب املدعــى عليــه األول أفــاد‬\n‫بأنــه وجــد إعــان يف قنــاة ‪ .....‬مــن قبــل شــخصي يلقــب‪( /‬فــرزت لــه‬\n‫ا براتــب ألفــان‬‫أوراق مســتقلة )وأتصــل بــه وطلــب منــه أن يكــون مراسـ ً‬\n‫وثمامنائــة ريــال فاتفقــا علــى ذلــك وعنــد االتفــاق بينهمــا طلــب منــه صــورة‬\n‫شــخصية لــه وصــورة مــن هويتــه حيــث ذكــر لــه بأنــه يعمــل يف جتــارة‬\n‫الذهــب وطلــب منــه مقابلتــه بحــي ‪ .....‬وحضــر لــه الشــخص امللقــب‪/‬‬\n‫(فــرزت لــه أوراق مســتقلة) وأعطــاه أوراق ومــن ضمنهــا الشــيك محــل‬\n\n\n                                                                                       ‫‪314‬‬\n\f      ‫الدعــوى وتفويــض باالســتالم وطلــب منــه إيصالهــا حملــل للذهــب‬\n      ‫واعتــرف انــه قدمهــا ملوظــف مبؤسســة و اســتلم عــدد (‪ )12‬ســبيكة‬\n      ‫ذهبيــةن عندهــا اتصــل بــه وطلــب منــه أن يســتقل ســيارة اجــره ويتقابــا‬\n      ‫لــدى فــرع البنــك ‪ .....‬واضــاف انــه عنــد خروجــه مــن احملــل حضــر لــه‬\n      ‫ثالثــة أشــخاص يســتقلون ســيارة نــوع ‪ .....‬بيضــاء ال يعــرف رقمهــا‬\n      ‫وقامــوا بإركابــه بالقــوة والهــرب بــه وإنزالــه يف أحــد األحيــاء بعــد‬\n      ‫الهــرب بالســبائك الذهبيــة فتوجــه ملنــزل أخيــه بحــي ‪ .....‬واضــاف بأنــه‬\n      ‫متكــن مــن كتابــة رقــم لوحــة الســيارة يف ورقــة وأنهــا موجــودة يف احملــل‬\n      ‫وباالنتقــال بــه إلــى نفــس احملــل‪ ،‬رجــع وقــال بأنهــا موجــودة مــع أخيــه‬\n      ‫‪ ،‬وأفــاد بأنــه لــم يتقــدم ببــاغ رســمي للجهــات األمنيــة مبــا حصــل لــه‪،‬‬\n      ‫وإال أنــه اتصــل بشــخص يقــال لــه واخبــره عــن أشــخاص قامــوا بخطفــه‬\n      ‫فطلــب منــه التوجــه ملركــز الشــرطة لإلبــاغ مبــا حصــل ‪ ،‬كمــا أفــاد‬\n      ‫بأنــه اتصــل مــرة أخــرى بأبــي ‪ .....‬وقــال بــأن اجلماعــة أتضــح انهــم يلعبــون‬\n      ‫وبضبــط افــادة املدعــو ســعودي اجلنســية مبوجــب الهويــة رقــم ()(الــذي‬\n      ‫يدعــي املدعــى عليــه االول انــه اتصــل عليــه ويدعى)افــاد انــه اتصــل عليــه‬\n      ‫املدعــى عليــه االول واخبــره عــن اشــخاص قامــوا بخطفــه فطلــب منــه‬\n      ‫اإلبــاغ ويف اليــوم اتصــل عليــه وأخبــره بــأن األشــخاص ميزحــون معــه‬\n      ‫وانــه لــم يحصــل لــه مشــكلة ابــدا فطلــب منــه احلضــور ملركــز شــرطة‬\n                      ‫النســيم بطلــب مــن ضابــط اخلفــر ولكنــه أغلــق جوالــه ‪.‬‬\n      ‫وقــد أســفرت إجــراءات التحقيــق عــن توجيــه االتهــام للمدعــى عليــه‬\n      ‫للمدعــى عليــه االول بتقــدمي شــيك مــزور ملؤسســة للذهــب واملجوهــرات‬\n      ‫لشــراء عــدد(‪ )12‬ســبيكة ذهبيــة وتواطؤهــم جميعــا يف اإلســتيالء علــى‬\n      ‫تلــك الســبائك الذهبيــة وتســترهم علــى اجلنــاة الهاربــن وقيــام الثانــي‬\n\n\n‫‪315‬‬\n\f‫بحيــازة وبيــع عدد(‪)4‬اربــع ســبائك ذهبيــة اتضــح انهــا مــن نفس الســبائك‬\n‫التــي قــام االول بشــرائها وقيــام الثالــث بخيانــة األمانــة املعاقــب علــى‬\n                                                                       ‫ذلــك شــرعا‪.‬‬\n‫باســتجواب املدعــى عليــه الثانــي أفــاد بأنــه تلقــى اتصــال مــن جــاره ‪......‬‬\n‫واخبــره بــان لديــه كميــه مــن الذهــب حتصــل عليهــا مــن احــد معارفــه‬\n‫ويرغــب يف بيعهــا واجتهــا ســويا وبحوزتهمــا أربــع ســبائك مــن الذهــب‬\n‫إلــى حــي ‪ .....‬لغــرض بيعهــا ومت القبــض عليــه وبإعــادة اســتجوابه افــاد‬\n‫بأنــه ذهــب حملــل ‪ .....‬بــال‪ .....‬بســيارة األخيــر فنــزل املدعــى عليــه لوحــده‬\n‫وقــام ببيــع الذهــب والبالــغ وزنــه أربعــة كيلــو اســتلم قيمــة الذهــب وقدره‬\n‫ثمامنائــة وســتون ألــف ريــال وطلــب منــه صاحــب احملــل أن يأتــي لــه بصورة‬\n‫هويــة صاحــب الذهــب ويف اليــوم التالــي اتصــل بــه صاحــب احملــل وقــال‬\n‫لــه ال تتصــرف يف املبلــغ قيمــة الذهــب واضــاف بانــه اتصــل بأبــي ‪.....‬‬\n‫وطلــب منــه هويــة صاحــب الذهــب فأخبــره بــان صاحــب الذهــب اغلــق‬\n‫جوالــه وقــال ثمنــي وثمنــك طلقــة رصــاص يقصــد التهديــد ‪.‬واضــاف انــه‬\n              ‫ذهــب ملركــز شــرطة الســليمانية برفقــة ومت القبــض عليــه ‪.‬‬\n‫وبضبــط افــادة ‪ /‬مينــي اجلنســية إقامــه رقــم ()حيــال مــا أفــاد بــه املدعــى‬\n‫عليــه الثانــي انكــر عالقتــه بالســبائك الذهبيــة وأبــدى اســتعداده‬\n‫ملواجهــة املتهــم‪ /‬كمــا نفــى معرفتــه باملدعــى عليهمــا‪ /‬و‪ ..... /‬وبإجــراء‬\n‫املواجهــة بــن املبلــغ‪ /‬واملتهــم‪ /‬علــي حيــال تشــابه اخلــط املــدون علــى‬\n‫الشــيك باخلــط املتعلــق باملتهــم والــذي يعمــل لديهــم بوظيفــة محاســب‬\n‫بشــركة(‪).....‬وقد لوحــظ قــوة حجــة املبلــغ وضعف جانــب الرد من املتهم‬\n‫وارتباكــه وبإجــراء املواجهــة بــن األول واملدعــو ‪ /‬ألدعــاء االول بأنــه‬\n‫قــام بإبــاغ املدعــو‪ /‬عــن أشــخاص قــام بخطفــه بعــد خروجــه مــن محــل‬\n\n\n                                                                                        ‫‪316‬‬\n\f      ‫« للمجوهــرات» واتضــح مــن خــال املواجــه ارتبــاك املتهــم‪ /‬وتضاربــه‬\n      ‫يف أقوالــه وعــدم اتزانــه ـ كمــا مت إعــداد املواجهــة بــن املدعــى عليــه‬\n      ‫الثانــي واملدعو‪./‬التهامــه لألخيــر بتســليمه اربــع ســبائك ذهــب وأتضــح‬\n      ‫مــن خــال املواجهــة إصــرار كل منهمــا علــى أقوالــه واتضــح قــوة حجــة‬\n      ‫الغيــر وضعــف حجــة املدعــى عليــه الثانــي (جــرى حفــظ االتهــام بحــق ‪)/‬‬\n                                                ‫وذلــك لألدلــة والقرائــن التاليــة ‪-:‬‬\n      ‫‪1‬ـ مــا تضمنــه اعتــراف املدعــى عليــه األول املنــوه عنــه املــدون علــى‬\n      ‫الصفحــات رقم(‪)11-4‬مبلــف االســتدالل املرفــق علــى اللفــة رقــم(‪)64‬‬\n      ‫‪2‬ـ مــا تضمنتــه اقــوال املدعــى عليــه الثانــي مــن قيامــه ببيــع ســبائك‬\n      ‫ذهــب اتضــح انــه معمــم عنهــا‪ ،‬املنــوه عنهــا املدونــة علــى الصفحــات رقــم‬\n      ‫(‪ )11-3،8-1‬مبلــف االســتدالل املرفــق علــى اللفة(‪)65‬واملدونــة علــى‬\n            ‫الصفحــات رقــم(‪ )2-1‬مبلــف االســتدالل املرفــق علــى اللفــة(‪)64‬‬\n               ‫‪3‬ـ ما تضمنه التقرير الفني املرفق على اللفات رقم(‪)159-146‬‬\n      ‫‪4‬ـ مــا تضمنتــه إفــادة موظفــي مكتــب املنــوه عنهــا املدونــة علــى‬\n      ‫الصفحــات رقــم (‪ )10-8‬مبلــف االســتدالل املرفــق علــى املرفــق لفــه‬\n                                                                              ‫رقــم(‪)63‬‬\n                                          ‫‪5‬ـ تناقض املدعى عليه األول يف أقواله‪.‬‬\n      ‫‪6‬ـ محاضــر املواجهــة املنــوه عنهــا املدونــة علــى الصفحــات رقــم (‪1‬ـ‪)3‬‬\n                                 ‫مبلــف االســتدالل املرفــق علــى اللفــة رقــم(‪)17‬‬\n                ‫وببحث سوابقهم اتضح خلو صحائف سوابقهم من أي سابقة‪.‬‬\n      ‫وحيــث إن مــا أق ــدم عل ــيه ال ــمذكورون ف ــعل م ــحرم وم ــعاقب عليــه‬\n      ‫شــرع ًا لــذا أطلــب إثبــات مــا أســند إليهــم واحلكــم عليهــم بعقوبــة‬\n      ‫تعزيريــة بحقهــم تزجرهــم وتــردع غيرهــم ‪،‬والتشــديد عليهــم يف ذلــك‬\n\n\n‫‪317‬‬\n\f‫خلطــورة مــا أقدمــو عليــه ‪ .‬وبعــرض الدعــوى علــى املدعــى عليــه األول‬\n‫أجــاب قائــا مــا ذكــره املدعــي العــام مــن قيامــي بتقــدمي شــيك ملؤسســة‬\n‫للذهــب واملجوهــرات صحيــح ولكــن لــم أكــن أعلــم أنــه مــزور والــذي‬\n‫حصــل أن أحــد االشــخاص اتصلــت بــه مــن أجــل البحــث عــن عمــل حيــث‬\n‫وجــدت اســمه ورقمــه يف قنــاة ‪ .....‬يبحــث عمــن يعمــل لديــه مراســا ثــم‬\n‫واعدتــه يف ‪ .....‬بالريــاض بعــد أن طلــب ذلــك وبالفعــل قابلتــه وإعطائــي‬\n‫ورقــا ملفوفــا ال أعــرف محتــواه وطلــب منــي أن أرســلها إلــى شــخص‬\n‫اســمه يعمــل لــدى محــل للذهــب فلمــا ســلمته الــورق امللفــوف عرفنــي‬\n‫وقــال أنــت املراســل فقلــت لــه نعــم فلمــا أراد أنــه يأتــي بالذهــب رفضــت‬\n‫تســلمه ثــم اتصلــت علــى الــذي اتصلــت عليــه ابتــداء وألــح علــي باســتالم‬\n‫الذهــب وبالفعــل اســتلمته ثــم قبــض علــى رجــان وأخــذا الذهــب وبعــد‬\n‫ذلــك نزلونــي يف حــارة مــن محــات وســجلت اســم الســيارة خلــف فاتــورة‬\n‫الذهــب هكــذا أجــاب كمــا أجــاب املدعــى عليــه الثانــي‪ :‬بقولــه عــن‬\n‫الســبائك األربــع الذهبيــة التــي ذكرهــا املدعــي العــام كانــت بالفعــل‬\n‫معــي وقــد اعطانــي إياهــا جــاري مــن أجــل بيعهــا ثــم بعتهــا ملؤسســة ‪.....‬‬\n‫مببلــغ وقــدره ثمامنائــة وســتون ألــف ريــال إال أنــه لــم يعطنــي الفاتــورة‬\n‫واإلثبــات ممــا اضطرنــي إلــى إبــاغ اجلهــات املختصــة ولــم تتجــاوب جهــة‬\n‫التحقيــق معــي للتحقــق مــع املدعــو هكــذا أجــاب ‪ ،‬كمــا أجــاب املدعى‬\n‫عليــه الثالــث قائــا إنــه ال صحــة ملــا ذكــره املدعــي مــن حيــث تواطئــي‬\n‫وخيانتــي لألمانــة والــذي حصــل أننــي اكتشــفت صــرف يف الشــيك‬\n‫فأبلغــت رئيــس احلســابات واملديــر املالــي ولــم أزور الشــيك علمــا بأننــي‬\n‫علــى وشــك الســفر لبلــدي هكــذا أجــاب عليــه ســألت املدعــي العــام عــن‬\n‫بينتــه علــى مــا أنكــره املدعــى عليهــم فقــال بينتــي حتصــر فيمــا ذكرتــه‬\n\n\n                                                                                     ‫‪318‬‬\n\f      ‫يف الالئحــة واملعاملــة عليــه رفعــت اجللســة الســاعة ‪ 01:00‬للتأمــل وبــاهلل‬\n      ‫التوفيــق وصلــى اهلل علــى نبينــا محمــد حــرر ‪1433/01/11‬ه ـ و يف يــوم‬\n      ‫الســبت املوافــق‪ 1434/03/07‬ه ـ افتتحــت اجللســة الســاعة ‪10،15‬‬\n      ‫وفيهــا حضــر املدعــى عليهــم األول والثانــي والثالــث وكانــا قــد قــدم‬\n      ‫املدعــي باحلــق اخلــاص عريضــة الدعــوى املقيــدة لــدى احملكمــة برقــم‬\n      ‫يف ‪1434/2/23‬ه ـ إال أنــه لــم يراجــع لتحديــد موعــد للجلســة للنظــر يف‬\n      ‫احلــق اخلــاص وقــد جــرى ســؤال املدعــى عليهــم هــل لديهــم مــا يضيفونــه‬\n      ‫فقــال املدعــى عليــه األول إننــي خدعــت ولــم أكــن أعلــم باجلرميــة وقــال‬\n      ‫املدعــى عليــه الثانــي ليــس لــدي شــيء أضيفــه كمــا قــال املدعــى‬\n      ‫عليــه الثالــث لقــد ســبق أن أعطتنــي الشــركة التــي أعمــل بهــا شــهادة‬\n      ‫تزكينــي كمــا أنهــا لــم تتهمنــي باملشــاركة وأعطتنــي إخــاء طــرف‬\n      ‫هكــذا قــال وملزيــد مــن التأمــل رفعــت اجللســة إلــى يــوم األربعــاء املوافــق‬\n      ‫‪1434/3/11‬ه ـ الســاعة العاشــرة واختتمــت اجللســة الســاعة وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n      ‫حــرر يف ‪ 1434/03/07‬ه ـ ويف يــوم االثنــن املوافــق‪ 1434/04/15‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 01:30‬وفيهــا حضــر املدعــي باحلــق اخلــاص‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم () بصفتــه وكيــا عــن‬\n      ‫مصــرف ‪ .....‬مبوجــب الوكالــة رقــم وتاريخ‪1432/12/24‬ه ـ والتــي‬\n      ‫تخولــة حــق إقامــة الدعــاوى وتقــدمي البيانــات واملرافعــة واملدافعــة‬\n      ‫واملخاصمــة واجلــرح والتعديــل وكل مــا يتطلبــه النظــر يف الدعــوى كمــا‬\n      ‫حضــر املدعــى عليهــم الثالثــة وادعــى عليهــم قائــا لقــد قــام املدعــى‬\n      ‫عليهــم باالشــتراك بتزويــر وصــرف الشــيك املذكــور يف الئحــة املدعــي‬\n      ‫العــام وقــدره مليونــان وســتمائة ألــف وأربعــة وتســعون ألــف ريــال ومت‬\n\n\n‫‪319‬‬\n\f‫صرفــه لشــركة ثــم ملــا اتضــح أنــه مــزور قامــت موكلتــي بإعــادة املبلــغ‬\n‫لصاحبــة الشــيك وهــي شــركة ‪ .....‬أطلــب إلــزام املدعــى عليهــم الثالثــة‬\n‫متضامنــن بإعــادة املبلــغ لتواطئهــم هكــذا ادعــى وبعــرض الدعــوى‬\n‫اخلاصــة علــى املدعــى عليهــم الثالثــة أجابــوا قائلــن إنــه ال صحــة ملــا ورد‬\n‫يف دعــوى املدعــي اخلــاص وال عالقــة لنــا يف هــذه القضيــة عليــه جــرى‬\n‫ســؤال املدعــي اخلــاص عــن بينتــه فقــال أطلــب إمهالــي ورفعــت اجللســة‬\n‫لذلــك وحــدد لهمــا يــوم اإلربعــاء املوافق‪1434/05/01‬هـ الســاعة ‪11:00‬‬\n‫ورفعــت اجللســة الســاعة ‪ . 02:00‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/04/15‬ه ـ ويف‬\n‫يــوم الثالثــاء املوافــق‪ 1434/05/21‬ه ـ افتتحــت اجللســة الســاعة ‪11:00‬‬\n‫وفيهــا حضــر وكيــل املدعــي اخلــاص ولــم يحضــر املدعــى عليهــم‬\n‫الســجناء وقــد ســبق أن حــددت جلســة بتاريــخ ‪1434/5/1‬ه ـ وحضــر‬\n‫املدعــي اخلــاص ولــم يحضــر املدعــى عليهــم وجــرى ســؤاله عــن بينتــه‬\n‫فقــال لقــد قــام املدعــى عليهــم باالشــتراك بتزويــر الشــيك رقــم ‪ 796‬يف‬\n‫‪2011/8/22‬م مببلــغ مقــداره مليونــان وســتمائة وأربعــة وتســعون ألــف‬\n‫ريــال باســم شــركة ‪ .....‬ثــم اشــتركوا بتســليمه إلــى مكتــب للذهــب‬\n‫وأخذوا مقابله اثني عشــر ســبيكة ذهبية ومت إيداع الشــيك يف حســاب‬\n‫مكتــب ‪ .....‬ثــم اشــتكت شــركة ‪ .....‬موكلتــي وبعــد أن تأكــد‬\n‫ملوكلتــي أن الشــيك مــزور قامــت بإعــادة املبلــغ املذكــور لشــركة ‪.....‬‬\n‫ثــم أبــرز صــورة الشــيك املشــار إليــه كمــا أبــرز كشــف حســاب تضمــن‬\n‫إعــادة املبلــغ مــن قبــل موكلــة املدعــي اخلــاص إلــى شــركة ‪ .....‬ونظــرا‬\n‫لعــدم حلضــور املدعــى عليهــم فقــد قــررت رفــع اجللســة إلحضارهــم وحــدد‬\n‫موعــد آخــر وهــو يــوم األحــد املوافــق ‪1434/06/04‬هـ ـ الســاعة احلاديــة‬\n\n\n                                                                                      ‫‪320‬‬\n\f      ‫عشــرة وأغلقــت هــذه اجللســة الســاعة احلاديــة عشــرة والنصــف وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n      ‫حــرر يف ‪ 1434/05/21‬ه ـ ويف يــوم اإلثنــن املوافق‪1434/06/12‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 10:15‬حيــث لــم يحضــر املدعــى عليهــم مــن‬\n      ‫الســجن ســوى واحــد فقــط فقــد مت االتصــال علــى املدعــي اخلــاص‬\n      ‫وكالــة وإبالغــه بتأجيــل اجللســة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n      ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/06/12‬ه ـ ويف‬\n      ‫يــوم اإلثنــن املوافــق‪ 1434/06/19‬ه ـ افتتحــت اجللســة الســاعة ‪01:00‬‬\n      ‫وفيهــا حضــر املدعــى عليهــم الثالثــة كمــا حضــر وكيــل املدعي اخلاص‬\n      ‫وأبــرز فاتــورة حســاب خــاص بالبنــك يــدل علــى أن موكلــه قــام بإعــادة‬\n      ‫املبلــغ حلســاب ‪ .....‬وقــد جــرى الرجــوع إلــى املعاملــة فوجــدت بــن طياتهــا‬\n      ‫محضــر املواجهــة بــن املدعــى عليــه الثانــي واملدعــو التهامــه لألخيــر‬\n      ‫بتســليمه الســبائك األربــع الذهبيــة واتضحــت قــوة حجــة األخيــر وضعــف‬\n                                          ‫حجــة يف امللــف لفــة (‪ )102‬ص ــ‪ 8‬الثانــي‬\n      ‫كمــا اطلعــت علــى محضــر املواجهــة امللــف لفــة (‪ )170‬ص ــ‪ 2‬بــن‬\n      ‫املبلــغ واملدعــى عليــه الثالــث حيــال تشــابه اخلــط املــدون علــى الشــيك‬\n      ‫بخطــه وقــد الحــظ مــن أجــرى املواجهــة قــوة حجــة املبلــغ وضعــف جانــب‬\n      ‫املدعــى عليــه وارتباكــه وبعرضــه علــى املدعــى عليــه الثالــث قــال إن‬\n      ‫الضابــط لــم يحقــق كمــا اطلعــت أيضــا علــى التقريــر الفنــي الصــادر‬\n      ‫مــن شــعبة الفحــوص باألدلــة اجلنائيــة لفــة رقــم ( ‪ )159‬وتضمــن أن اخلــط‬\n      ‫والتوقيــع منســوخ كليــا وأنــه مبضاهــاة اخلــط اتضــح بأنــه مطابــق خلــط‬\n      ‫املدعــى عليــه الثالــث وبعرضــه عليــه قــال ‪ :‬كيــف أكتــب الشــيك‬\n      ‫بخــط يــدي وأفضــح نفســي وقــد جــرى تأمــل مــا ســلف فبنــاء علــى مــا‬\n\n\n‫‪321‬‬\n\f‫تقــدم مــن الدعــوى العامــة واخلاصــة وملــا جــاء يف إجابــة املدعــى عليــه‬\n‫األول مــن أنــه قــدم الشــيك وذكــر أنــه تســلم ورقــا ملفوفــا مــن شــخص‬\n‫تعــرف عليــه عــن طريــق قنــاة فضائيــة وســلمه كمــا يذكــر وأنــه تســلم‬\n‫الذهــب أيضــا وهــذا يــدل علــى اشــتراكه يف جرميــة االحتيــال وملــا‬\n‫جــاء يف جــواب املدعــى عليــه الثانــي مــن أن بعــض الســبائك الذهبيــة‬\n‫كانــت معــه وحيــث أنكــر املدعــى عليــه الثالــث وملــا جــاء يف محاضــر‬\n‫املواجهــة التــي مت تلخيصهــا مــن واقــع املعاملــة يف مطلــع التســبيب وملــا‬\n‫جــاء يف التقريــر الفنــي اخلــاص باملدعــى عليــه الثالــث لذلــك كلــه فقــد‬\n‫ثبــت لــدي اشــتراك املدعــى عليهمــا األول والثانــي يف جرميــة االحتيــال‬\n‫وتوجهــت التهمــة علــى املدعــى عليــه الثالــث مبشــاركته يف جرميــة‬\n‫االحتيــال وملــا جــاء يف قــرار يف قــرار مجلــس القضــاء الســابق رقــم يف‬\n‫‪1421/3/4‬ه ـ يف مدونــة األحــكام القضائيــة اإلصــدار األول ‪1428‬ه ـ‬\n‫ص ‪ 60‬و قــد قــرر مبــدأ قضائيــا يتعلــق بتضمــن املختلســن وملــا جــاء يف‬\n‫مواهــب اجلليــل نقــا عــن اإلمــام ابــن رشــد « إذا اجتمــع القــوم يف الغصــب‬\n‫أو الســرقة أو احلرابــة فــكل واحــد منهــم ضامــن جلميــع مــا أخــذوه ألن‬\n‫بعضهــم قــوي ببعــض كالقــوم يجتمعــون علــى قتــل رجــل فيقتــل جميعهــم‬\n‫بــه وإن ولــي القتــل أحدهــم» ‪ 316/6‬وحكمــت يف احلــق العــام مبــا يلــي ‪:‬‬\n‫أوال ‪ :‬ســجن املدعــى عليــه األول واملدعــى عليــه الثانــي ملــدة ســنتني وســتة‬\n‫أشــهر وحتتســب منهــا مــدة إيقافهمــا وجلــد كل واحــد منهمــا مائتــن‬\n‫وخمســن جلــدة مفرقــة علــى خمــس دفعــات كل دفعــة خمســون جلــدة‬\n‫بينهــن عشــرة أيــام علــى األقــل ثانيــا ‪ :‬ســجن املدعــى عليــه الثالــث ملــدة‬\n‫ســنتني وحتتســب منهــا مــدة إيقافــه وجلــده مئتــي جلــدة مفرقــة على أربع‬\n‫دفعــات كل دفعــة خمســون جلــدة بينهــن عشــرة أيــام كمــا حكمــت‬\n\n\n                                                                                      ‫‪322‬‬\n\f      ‫باحلــق اخلــاص مبــا يلــي ‪ :‬أوال ‪ :‬إلــزام املدعــى عليهمــا األول والثانــي بدفــع‬\n      ‫مبلــغ قــدره مليونــان وســتمائة وأربعــة وتســعون ريــاال لصالــح مــوكل‬\n      ‫املدعــي اخلــاص متضامنــن ال يبــرأ أحدهمــا إال بســداد املبلــغ كامــا‬\n      ‫منهمــا أو أحدهمــا ثانيــا ‪ :‬رددت دعــوى املدعــي اخلــاص جتــاه املدعــى‬\n      ‫عليــه الثالــث ألن األدلــة ال تكفــي إلثبــات احلــق اخلــاص وبعــرض احلكــم‬\n      ‫علــى املدعــى عليهــم اعتــرض املدعــى املدعــى عليهمــا األول والثانــي‬\n      ‫والثالــث وطلبــوا اســتئناف احلكــم بالئحــة اعترضيــة وأفهمــوا أن عليهــم‬\n      ‫مراجعــة احملكمــة خــال عشــرة أيــام ولهــم بعــد تســلم نســخة احلكــم‬\n      ‫تقــدمي الالئحــة االعتراضيــة خــال ثالثــن يومــا وإذا لــم يقدمــوا الالئحــة‬\n      ‫فســيتم رفــع املعاملــة حملكمــة االســتئناف كمــا قــرر املدعــي اخلــاص‬\n      ‫وكالــة االعتــراض علــى احلكــم وأفهــم أن عليــه مراجعــة احملكمــة‬\n      ‫خــال عشــرة أيــام لتســلم نســخة احلكــم ولــه بعدهــا ثالثــون يومــا وإذا‬\n      ‫لــم يحضــر خاللهــا اكتســب احلكــم القطعيــة يف احلــق اخلــاص بالنســبة‬\n      ‫لــه ونطــق باحلكــم الســاعة ‪ 01:30‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n          ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/06/19‬ه ـ‬\n      ‫ويف يــوم الثالثــاء املوافــق‪ 1434/07/18‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫‪ 10:30‬وفيهــا حضــر املدعــى عليــه األول واملدعــى عليــه الثانــي واملدعــى‬\n      ‫عليــه الثالــث وتســلم كل واحــد منهــم نســخة مــن احلكــم وأفهمــوا‬\n      ‫أن لهــم ثالثــن يومــا وإذا لــم يقدمــوا اعتراضهــم خاللهــا فســيتم رفــع‬\n      ‫املعاملــة حملكمــة االســتئناف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n      ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/07/18‬ه ـ ويف‬\n      ‫يــوم األحــد املوافــق‪ 1434/07/30‬ه ـ افتتحــت اجللســة الســاعة ‪11:30‬‬\n      ‫وفيهــا حضــر وكيــل املدعــي اخلــاص ســعودي اجلنســية بالبطاقــة رقــم‬\n\n\n‫‪323‬‬\n\f‫مبوجــب الوكالــة رقــم وتاريــخ ‪1432/12/24‬ه ـ الصــادر مــن كاتــب‬\n‫العــدل املكلــف يف وزارة التجــارة والصناعــة والتــي تخولــه حــق تقــدمي‬\n‫االعتــراض وتســلم نســخه مــن احلكــم وأفهــم أن لــه ثالثــن يوم ـ ًا‬\n‫وإذا لــم يقــدم أعتراضــه خاللهــا اكتســب احلكــم القطعيــة يف احلــق‬\n‫اخلــاص ‪ .‬وبــاهلل التوفيــق ويف يــوم الســبت املوافــق ‪ 1434/08/06‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪10:15‬وفيهــا حضــر ‪ .....‬مينــي اجلنســية مبوجــب‬\n‫اإلقامــة رقــم‪ .....‬بصفتــه وكيــا عــن مبوجــب الوكالــة رقــم ‪ .....‬وتاريــخ‬\n‫‪1434/7/30‬ه ـ الصــادرة مــن كاتــب عــدل احلائــر وتخولــه حــق تقــدمي‬\n‫الالئحــة االعتراضيــة وســماع الدعــوى والــرد عليهــا وقــدم الئحتــه‬\n‫االعتراضيــة واملكونــة مــن ســتة عشــر صفحــة‪ .‬وبــاهلل التوفيــق ويف يــوم‬\n‫االثنــن املوافــق ‪1434/08/08‬ه ـ افتتحت اجللســة الســاعة ‪ 11:15‬وفيها‬\n‫حضــر ‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‪ ....‬بصفتــه‬\n‫ا عــن شــركة ‪ .....‬مبوجــب الوكالــة رقــم وتاريــخ ‪1432/12/24‬‬          ‫وكيـ ً‬\n‫الصــادرة مــن كاتــب العــدل املكلــف يف وزارة التجــارة والصناعــة‬\n‫وقــدم الئحتــه االعتراضيــة واملكونــة مــن صفحتــن وبــاهلل التوفيــق ويف‬\n‫يــوم األربعــاء املوافــق‪ 1434/08/10‬ه ـ افتتحــت اجللســة الســاعة ‪10:15‬‬\n‫ا عــن‬  ‫وفيهــا حضــر ‪ ......‬ســعودي اجلنســية مبوجــب الهويــة رقــم‪ .....‬وكيـ ً‬\n‫املدعــى عليــه مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة‬\n‫رقــم وتاريــخ ‪1430/07/29‬ه ـ وقــدم الالئحــة االعتراضيــة واملكونــة‬\n‫مــن ثــاث صفحــات كمــا حضــر ســعودي اجلنســية مبوجــب الهويــة رقــم‬\n‫ا عــن املدعــى عليــه نفســه مبوجــب الوكالــة الصــادرة مــن كاتب‬     ‫وكيـ ً‬\n‫عــدل احلائــر رقــم وتاريــخ ‪1434/8/7‬ه ـ وقــدم الئحتــه االعتراضيــة‬\n‫واملكونــة مــن خمــس صفحــات ‪ .‬وبــاهلل التوفيــق احلمــد هلل وحــده وبعــد‬\n\n\n                                                                                    ‫‪324‬‬\n\f      ‫فلــدي أنــا القاضــي يف احملكمــة اجلزائيــة بالريــاض والقائــم بعمــل‬\n      ‫فضيلــة القاضــي‪ ........‬القاضــي باحملكمــة اجلزائيــة بالريــاض ففــي يــوم‬\n      ‫األربعاء املوافق‪ 1434/08/17‬هـ افتتحت اجللسة الساعة ‪ 10:00‬وفيها‬\n      ‫حضــر املدعــى عليــه الثالــث وقــدم الئحتــه االعتراضيــة املكونــة مــن‬\n      ‫اربــع ورقــات ومرفــق معهــا مجموعــه أوراق وبــاهلل التوفيــق‪ ،‬وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/08/17‬ه ـ‬\n      ‫احلمــد هلل وحــده‪ ،‬وبعــد‪ :‬فقــد اطلعنــا نحن قضــاة الدائرة اجلزائية األولى‬\n      ‫مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيس‬\n      ‫احملكمــة اجلزائيــة بالريــاض املكلــف برقــم وتاريــخ ‪1434/9/24‬ه ـ‬\n      ‫واملرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‪/‬‬\n      ‫برقــم وتاريــخ ‪1434/7/12‬ه ـ واخلــاص بدعــوى املدعــي العــام ضــد ‪/‬‬\n      ‫ورفقــاه‪ ،‬جنســيته (مينــي) وموضوعهــا احتيــال‪ ،‬وقــد انتهــت الدراســة‬\n      ‫والتدقيــق باملصادقــة علــى احلكــم لعــدم موجــب املالحظــة‪ .‬مــع تنبيــه‬\n      ‫فضيلتــه إلــى تدويــن اطالعــه علــى اللوائــح االعتراضيــة‪ ،‬وتدويــن اســم‬\n      ‫املدعــي العــام وفق ـ ًا للمــادة (‪ )156‬مــن نظــام اإلجــراءات اجلزائيــة‪،‬‬\n      ‫وتصحيــح مــا علــم عليــه بقلــم الرصــاص‪ .‬واهلل املوفــق‪ ،‬وصلــى اهلل‬\n                           ‫وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪325‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":310,"source_page_end":325,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"54a38eb813b965bea35b5f93f213e4f245889bbfaef949383a21a3f733ca5346","normalized_text_hash":"19d1448e15687ead939936460f128cd9aee80da20bd49e4b68acd2cef3aea10c","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p310-34266892"},{"id":"2cc972ef-1040-571c-8750-de632b628725","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -خطف حقيبة -عدم قبول الرجوع عن االقرار يف حقوق اآلدمين -صغر سن املتهم مبرر مخفف للعقوبة .","document_number":"34279682","case_number":"34167067","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":"الدائرة اجلزائية الثالثية األولى رقم /34298500ج 1/وتاريخ","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/25","year":"1434","subject":"سرقة -خطف حقيبة -عدم قبول الرجوع عن االقرار يف حقوق اآلدمين -صغر سن املتهم مبرر مخفف للعقوبة .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34279682 :‬تاريخه‪1434/7/25 :‬هـ‬\n                    ‫رقم الدعوى‪34167067 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34298500‬تاريخه‪1434/8/16 :‬هـ‬\n\n\n\n‫ســرقة ‪ -‬خطــف حقيبــة ‪ -‬عــدم قبــول الرجــوع عــن االقــرار يف حقــوق‬\n               ‫اآلدميــن ‪ -‬صغــر ســن املتهــم مبــرر مخفــف للعقوبــة ‪.‬‬\n\n\n\n\n‫ض َب ْع َد ِإ ْص َل ِح َها} وقال تعالى‪:‬‬        ‫‪ -‬قال اهلل تعالى ‪َ { :‬و َل ُت ْف ِس ُدوا ِف ْ َ‬\n                                          ‫ال ْر ِ‬\n‫حــب ْالُ ْع َتدِ َيــن} وقــال صلــى اهلل عليــه وســلم ‪:‬‬                ‫{ َوال َت ْع َتـ ُـدوا ِإ َّن َّ َ‬\n                                                               ‫الل ال ُي ِ ُّ‬\n                ‫وعرضــه))‪.‬‬\n                       ‫ُ‬          ‫دمـ ُه وما ُلـ ُه‬\n                                                  ‫((كل املســلم علــى املســلم حــرا ٌم ُ‬          ‫ُّ‬\n‫‪ -‬قــال ابــن قدامــة يف املغنــي ‪ « :‬فأمــا حقــوق اآلدميــن ‪ ،‬وحقــوق اهلل‬\n‫التــي ال تــدرأ بالشــبهات كالــزكاة والكفــارات ‪ ،‬فــا يقبــل رجوعــه‬\n                                                   ‫عنهــا ‪ ،‬وال نعلــم يف هــذا خالف ـ ًا»‪.‬‬\n\n\n\n‫اتهــام املدعــي العــام للمدعــى عليــه بقيامــه باالشــتراك مــع آخــر بنشــل‬\n‫حقيبــة امــرأة يطلــب إثبــات ما أســند إليه ‪ ،‬واحلكــم عليه بعقوبة تأديبية‬\n‫تردعــه وتقــوم مــن ســلوكه‪ .‬حيــث قبــض عليــه بتاريــخ ‪1434/2/12‬ه ـ‬\n‫وأحيــل إلــى دار املالحظــة االجتماعيــة بالدمــام وأفــرج عنــه بالكفالــة‬\n‫بتاريــخ ‪1434/2/14‬ه ـ بنــاء علــى توجيه قاضي األحداث‪ ،‬وباســتجواب‬\n‫املدعــى عليــه أقــر بقيامــه بنشــل حقيبــة املبلغــة أثنــاء قيادتــه لدراجتــه‬\n‫الناريــة ويرافقــه شــخص آخــر (فــرزت لــه أوراق مســتقلة)‪ ،‬وصــدق‬\n\n                                                                                                               ‫‪326‬‬\n\f                                                            ‫إقــراره شــرع ًا بذلــك‪.‬‬\n      ‫ومبواجهــة املدعــى عليــه يف مجلــس احلكــم أنكــر االتهام ونظــر ًا لصغر‬\n      ‫ســن املتهــم وعــدم وجــود ســوابق وانتهــاء احلــق اخلــاص قــررت احملكمــة‬\n      ‫بســجنه شــهرين وجلــده مائــة وخمســون جلــدة وأخــذ التعهــد عليــه وقــد‬\n      ‫قنــع املدعــى عليــه وأعتــرض املدعــى العــام وجــرى تصديــق احلكــم مــن‬\n                                                           ‫محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة علــى مــن ال نبــي بعــده وبعــد فلــدي أنــا‬\n      ‫‪ ....‬القاضــي باحملكمــة اجلزائيــة باألحســاء وبنــاء علــى املعاملــة‬\n      ‫الــواردة إلينــا مــن دائــرة التحقيــق واالدعــاء العــام مبحافظــة األحســاء‬\n      ‫برقــم ‪ 5303‬وتاريــخ ‪1434/04/10‬ه ـ واملقيــدة باحملكمــة برقــم‬\n      ‫‪ 34891155‬وتاريــخ ‪1434/04/13‬ه ـ واحملالــة لــي برقــم ‪34167067‬‬\n      ‫وتاريــخ ‪1434/04/13‬ه ـ ففــي هــذا اليــوم الســبت ‪1434/06/03‬ه ـ‬\n      ‫افتتحــت اجللســة االولــى يف متــام التاســعة وفيهــا حضــر املدعــي العــام‬\n      ‫‪ .....‬املعمــد بالترافــع أمــام احملكمــة طرفنــا مبوجــب خطــاب ســعادة‬\n      ‫رئيــس دائــرة االدعــاء العــام مبحافظــة األحســاء ذي الرقــم ‪13415‬‬\n      ‫والتاريــخ ‪1433/12/1‬ه ـ وقــال يف دعــواه بصفتــي مدعي ـ ًا عام ـ ًا يف‬\n      ‫دائــرة االدعــاء العــام مبحافظــة األحســاء أدعــي علــى ‪ :‬احلــدث ‪.... /‬‬\n      ‫‪ 16 ،‬عام ـ ًا ‪ ،‬طالــب ‪ ،‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫(‪ ، )...‬قبــض عليــه بتاريــخ ‪1434/2/12‬ه ـ وأحيــل إلــى دار املالحظــة‬\n      ‫االجتماعيــة بالدمــام وأفــرج عنــه بالكفالــة بتاريــخ ‪1434/2/14‬ه ـ‬\n      ‫بنــاء علــى توجيــه قاضــي األحــداث ‪ ،‬يســكن االحســاء حــي ‪. ....‬حيــث‬\n‫‪327‬‬\n\f‫أنــه مت القبــض عليــه بتاريــخ ‪1434 / 4 / 12‬ه ـ مــن قبــل املدعــو ‪....‬‬\n‫وقــام بتســليمه لرجــال الدوريــات األمنيــة بعــد ورود بــاغ مــن املواطنــة‬\n‫‪ ....‬تفيــد فيــه بتعرضهــا لنشــل حقيبتهــا مــن قبــل شــخصني كانــا علــى‬\n‫دراجــة ناريــة ‪.‬وبضبــط أقــوال املدعــوة ‪( ....‬ســعودية اجلنســية) أفــادت‬\n‫بأنهــا أثنــاء ســيرها باحلــي برفقــة ابنتهــا قامــا شــخصني يســتقالن دراجــة‬\n‫ناريــة قائدهــا يرتــدي جاكيــت أحمــر اللــون واآلخــر قــام بنشــل حقيبتهــا‬\n‫التــي حتملهــا علــى كتفهــا ورماهــا علــى األرض فقامــت باالتصــال علــى‬\n‫ابنهــا الــذي بــدوره قــام بالقبــض علــى املدعــى عليــه وتســليمه لرجــال‬\n‫الدوريــات األمنيــة ‪ .‬وباســتجواب املدعــى عليــه أقــر بقيامــه بنشــل حقيبــة‬\n‫املبلغــة أثنــاء قيادتــه لدراجتــه الناريــة ويرافقــه شــخص آخــر (فــرزت لــه‬\n‫أوراق مســتقلة)‪ ،‬وصــدق إقــراره شــرع ًا بذلــك ‪ .‬وقــد أســفر التحقيــق‬\n‫عــن توجيــه االتهــام لــه باالشــتراك مــع آخــر بنشــل حقيبــة امــرأة ؛ وذلــك‬\n                                                      ‫لألدلــة والقرائــن التاليــة ‪:‬‬\n‫‪ .1‬إقــراره املصــدق شــرع ًا املــدون علــى الصفحــة رقــم (‪ )6‬مــن دفتــر‬\n                                               ‫التحقيــق املرفــق لفــه رقــم (‪. )1‬‬\n‫‪ .2‬أقــوال املبلغــة املدونــة علــى الصفحــة رقــم (‪ )11_10‬مــن دفتــر‬\n                                            ‫التحقيــق املرفــق لفــه رقــم (‪. )12‬‬\n                                     ‫‪ .3‬محضر القبض املرفقة لفه رقم (‪. )3‬‬\n‫وحيــث إن مــا أقــدم عليــه املدعــى عليــه وهــو بكامــل أهليتــه املعتبــرة‬\n‫شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا ؛ أطلــب إثبــات مــا أســند إليــه‪،‬‬\n‫واحلكــم عليــه بعقوبــة تأديبيــة تردعــه وتقــوم مــن ســلوكه ‪(.‬علم ـ ًا أن‬\n‫احلــق اخلــاص انتهــى بالتنــازل) ‪.‬هكــذا أدعــى ورفعــت اجللســة لطلــب‬\n‫املدعــى عليــه ويف جلســة اخــرى حضــر الطرفــان وبعــد التأكــد مــن‬\n\n\n                                                                                        ‫‪328‬‬\n\f      ‫هويــة املدعــى عليــه جــرى عــرض دعــوى املدعــي العــام عليــه فأجــاب‬\n      ‫ا ‪ :‬مــا ذكــره املدعــي العــام مــن اتهامــي باالشــتراك مــع شــخص‬                          ‫قائ ـ ً‬\n      ‫آخــر باختــاس حقيبــة امــرأة غيــر صحيــح والصحيــح أ َّنــه بينــي وبــن‬\n      ‫ابــن املدعيــة مشــاكل فاتهمونــي بهــذه التهمــة هكــذا أجــاب ثــم جــرى‬\n      ‫االطــاع علــى جميــع أوراق املعاملــة ومنهــا ‪ :‬إقــرار املدعــى عليــه املصادق‬\n      ‫عليــه شــرع ًا املوجــود علــى الصحيفــة(‪ )6‬مــن ملــف التحقيــق لفــة(‪)1‬‬\n      ‫املتضمــن مــا نصــه ‪( :‬أقـ ُّـر بأننــي قمــت بنشــل شــنطة امــرأة حيــث كنــت‬\n      ‫أقــود دراجتــي الناريــة وبعــد أن صرخــت املــرأة قمــت برمــي الشــنطة )‬\n      ‫ا ‪ :‬صحيــح توقيعــي علــى‬      ‫ا‪ .‬ه ـ وبعرضــه علــى املدعــى عليــه أجــاب قائ ـ ً‬\n      ‫اإلقــرار ولكننــي لــم أقــرأ مــا فيــه هكــذا قــرر كمــا جــرى االطــاع‬\n      ‫علــى كــرت ســوابق املدعــى عليــه املتضمــن عــدم وجــود ســوابق عليــه‬\n      ‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وبعــد النظــر يف حــال املدعــى‬                 ‫فبنـ ً‬\n      ‫عليــه والتأكــد مــن أهليتــه وبعــد دراســة أوراق املعاملــة وتأملهــا ومبــا‬\n      ‫أن املدعــى عليــه أنكــر دعــوى املدعــي العــام باتهامــه باالشــتراك مــع‬                             ‫َّ‬\n      ‫شــخص آخــر باختــاس حقيبــة امــرأة وال بينــة للمدعــي العــام ســوى‬\n      ‫إقــراره املصــادق عليــه شــرع ًا وقــد رجــع عنــه وملــا قــرره أهــل العلــم مــن‬\n      ‫أ َّنــه ال يقبــل الرجــوع عــن اإلقــرار يف التعازيــر ‪ ،‬قــال ابــن قدامــة يف‬\n      ‫املغنــي ‪ « :‬فأمــا حقــوق اآلدميــن ‪ ،‬وحقــوق اهلل التــي ال تــدرأ بالشــبهات‪،‬‬\n      ‫كالــزكاة والكفــارات ‪ ،‬فــا يقبــل رجوعــه عنهــا ‪ ،‬وال نعلــم يف هــذا‬\n      ‫أن مــا صــدر مــن املدعــى عليــه مــن احملــرم شــرع ًا قــال‬             ‫خالف ـاً» ومبــا َّ‬\n      ‫{وال‬‫ض َب ْعـ َـد ِإ ْص َلحِ َهــا } وقــال تعالــى ‪َ :‬‬\n                                                           ‫ال ْر ِ‬‫{و َل ُت ْف ِسـ ُـدوا ِف ْ َ‬\n                                                                                             ‫تعالــى ‪َ :‬‬\n       ‫الل ال ُي ِ ُّحــب ْال ُْع َتدِ َيــن } وقــال صلــى اهلل عليــه وســلم ‪(( :‬كلُّ‬ ‫َت ْع َتـ ُـدوا ِإ َّن َّ َ‬\n      ‫وعرضــه)) ممــا يســتوجب تعزيــر‬   ‫ُ‬      ‫دم ـ ُه وما ُل ـ ُه‬\n                                                                 ‫ـرام ُ‬\n                                                                      ‫املســلم علــى املســلم حـ ٌ‬\n\n‫‪329‬‬\n\f‫املدعــى عليــه ويتوجــه تخفيــف العقوبــة عليــه لصغــر ســنه ولعــدم وجــود‬\n‫ســوابق عليــه والنتهــاء احلــق اخلــاص بالتنــازل لــذا كلــه وألجــل احلــق العــام‬\n‫ـدي إدانــة املدعــى‬\n                   ‫حكمــت علــى املدعــى عليــه مبــا يلــي ‪ :‬أوالً‪ /‬ثبــت لـ َّ‬\n‫عليــه باالشــتراك مــع شــخص آخــر باختــاس حقيبــة امــرأة‪ .‬ويعــزر ألجــل‬\n‫ذلــك بســجنه شــهرين حتتســب منهــا املــدة التــي أوقــف فيهــا علــى ذمــة‬\n‫القضيــة وبجلــده مائــة وخمســون جلــدة مفرقــة علــى ثــاث دفعــات كل‬\n‫دفعــة خمســون جلــدة وبــن كل دفعــة وأخــرى مــدة ال تقــل عــن عشــرة‬\n‫أيــام ‪ .‬ثاني ـ ًا ‪ /‬يؤخــذ عليــه التعهــد بعــدم العــودة ملثــل مــا صــدر منــه ‪.‬‬\n‫وبتــاوة احلكــم علــى الطرفــن وإفهــام املدعــى عليــه بحقــه يف اســتئناف‬\n‫احلكــم قــرر قناعتــه بــه وطلــب املدعــي العــام رفــع كامــل أوراق املعاملــة‬\n‫حملكمــة االســتئناف لتدقيــق احلكــم دون الئحــة اعتراضيــة مكتفي ـ ًا‬\n‫مبــا ورد يف الئحــة الدعــوى وأقفلــت اجللســة الســاعة احلاديــة عشــرة‬\n‫وصلــى اهلل وسـلَّم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن‪ .‬حــرر‬\n                                                             ‫يف ‪1434/07/25‬هــ‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي‬\n‫يــوم االثنــن ‪1434/08/29‬ه ـ فتحــت اجللســة الثالثــة الســاعة العاشــرة‬\n‫وخمســة عشــر دقيقــة صباح ـ ًا وقــد عــادت املعاملــة املتعلقــة بالدعــوى‬\n‫ضــد ‪ .....‬يف قضيــة ( اختــاس ) مــن محكمــة االســتئناف باملنطقــة‬\n‫الشــرقية مبوجــب خطــاب فضيلــة رئيســها ذي الرقــم‪341913821‬‬\n‫والتاريــخ ‪1434/08/24‬ه ـ مرفق ـ ًا بهــا قــرار أصحــاب الفضيلــة قضــاة‬\n‫الدائــرة اجلزائيــة الثالثيــة األولــى رقــم ‪/34298500‬ج‪ 1/‬وتاريــخ‬\n‫‪1434/08/16‬ه ـ وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون‬\n‫ومفصــل فيــه ‪ :‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا‬\n                                                         ‫املصادقــة علــى احلكــم‪.‬‬\n                                                                                         ‫‪330‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":326,"source_page_end":330,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"e3caf7dfef4e05fc64afcc48c01906d9400076e89c6b9cf5d0d605afbed79eda","normalized_text_hash":"2080f0bb2b77fac9c87b014cb6b9a39fadd2d22719be2a83f45666ce8656c7ab","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p326-34279682"},{"id":"5335a821-fc0f-5e01-a339-6fd46bc79d61","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة ماكينة بحرية -خيانة أمانة -متكن شخص من السرقة نظير مقابل مالي -تفريط وعبث بأماك الدولة -رجوع عن إقرار مصدق شرع ا وادعاء اإلكراه النتزاعه -ثبوت اإلدانة مبوجب إقرار مصدق شرع ا -تعزير بالسجن واجللد.","document_number":"34240590","case_number":"34200198","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة فرسان ثم جرى االطاع على صحيفة سوابق املدعى عليه فوجدت أنه ال توجد سوابق مسجلة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/13","year":"1434","subject":"سرقة -سرقة ماكينة بحرية -خيانة أمانة -متكن شخص من السرقة نظير مقابل مالي -تفريط وعبث بأماك الدولة -رجوع عن إقرار مصدق شرع ا وادعاء اإلكراه النتزاعه -ثبوت اإلدانة مبوجب إقرار مصدق شرع ا -تعزير بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34240590:‬تاريخه‪1434/6/13 :‬هـ‬\n                          ‫رقم الدعوى‪34200198:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34290461‬تاريخه‪1434/8/7 :‬هـ‬\n\n\n\n      ‫ســرقة ‪ -‬ســرقة ماكينــة بحريــة ‪ -‬خيانــة أمانــة ‪ -‬متكــن شــخص مــن‬\n      ‫الســرقة نظيــر مقابــل مالــي ‪ -‬تفريــط وعبــث بأمــاك الدولــة ‪ -‬رجــوع‬\n      ‫عــن إقــرار مصــدق شــرع ًا وادعــاء اإلكــراه النتزاعــه ‪ -‬ثبــوت اإلدانــة‬\n                     ‫مبوجــب إقــرار مصــدق شــرع ًا‪ -‬تعزيــر بالســجن واجللــد‪.‬‬\n\n\n\n\n                        ‫‪ -1‬قوله صلى اهلل عليه وسلم (من غشنا فليس منا )‪.‬‬\n                                         ‫‪ -2‬ما قرره الفقهاء ال عذر ملن أقر‪.‬‬\n\n\n\n\n      ‫الئحــة الدعــوى ضــد املدعــى عليــه يعمــل خفير ًا بحرس احلــدود بتمكني‬\n      ‫شــخص مــن ســرقة ماكينــة واســطة بحريــة تابعــه حلــرس احلــدود مقابــل‬\n      ‫مبلــغ مالــي ‪ ،‬طلــب املدعــي العــام اثبــات مــا اســند اليــه واحلكــم عليــه‬\n      ‫بعقوبــة تعزيريــة ‪ ،‬مت القبــض علــى املدعــى عليــه بعــد قيــام املنــاوب مــن‬\n      ‫الشــرطة العســكرية بقطــاع حــرس احلــدود بجــرد الوســائط البحريــة‬\n      ‫املتحفــظ عليهــا والحــظ فــك ماكينــة منهــا ووجــود اثــار دمــاء واثــار‬\n      ‫ســحب واشــارت املعلومات االســتخباراتية اتهام املدعى عليه عســكري‬\n      ‫يعمــل خفيــر ًا بتمكــن الغيــر مــن ســرقتها مبقابــل مــادي وصــدق علــى‬\n      ‫ذلــك بعــد اســتجوابه ومتــت املصادقــة عليــه شــرعاً‪ ،‬أنكــر املدعــى عليــه‬\n\n‫‪331‬‬\n\f‫الدعــوى ‪ ،‬تبــن وجــود إقــرار مصــدق شــرع ًا للمدعــى عليــه‪ ،‬ادعــى‬\n‫املدعــى عليــه اإلكــراه بانتــزاع اإلقــرار ‪ ،‬واســتبان للمحكمــة عــدم‬\n‫وجــود ببينــة علــى دعــوى اإلكــراه ‪ ،‬وثبــت إدانــة املدعــى عليه‪ ،‬حكمت‬\n‫احملكمــة بتعزيــر املدعــى عليــه بالســجن واجللــد‪ -‬تصديــق احلكــم مــن‬\n                                                  ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n‫أنــا ‪ .............‬القاضــي يف احملكمــة اجلزائيــة بجــازان وبنــاء علــى‬\n‫املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة اجلزائيــة بجــازان‬\n‫برقــم ‪ 34200198‬وتاريــخ ‪ 1434/04/30‬ه ـ املقيــدة باحملكمــة برقــم‬\n‫‪ 341067201‬وتاريــخ ‪ 1434/04/30‬ه ـ ففــي يــوم الثالثــاء املوافــق‬\n‫‪ 1434/06/13‬ه ـ افتتحــت اجللســة الســاعة احلاديــة عشــرة صباح ـ ًا‬\n‫وفيهــا حضــر املدعــي العــام ‪ .............‬املعمــد بالعمــل مبوجــب خطــاب‬\n‫رقــم ‪ .............‬وتاريــخ ‪1433/03/22‬ه ـ وحضــر املدعــى عليــه ‪.............‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).............‬وتاريــخ‬\n‫ا يف دعــواه أنــه بتاريــخ‬    ‫‪1423/06/26‬ه ـ وادعــى املدعــي العــام قائ ـ ً‬\n‫‪1433/11/27‬ه ـ أثنــاء قيــام املنــاوب بقســم الشــرطة العســكرية‬\n‫بقطــاع حــرس احلــدود بفرســان بجــرد الوســائط املتحفــظ عليهــا الحــظ‬\n‫فــك ماكينــة للواســطة املســماة (‪ ).............‬رقــم (‪ ).............‬ووجــود آثــار‬\n‫دمــاء وآثــار ســحب للماكينــة وأشــارت املعلومــات االســتخباراتية لديهــم‬\n‫باتهــام ‪ .............‬و ‪( .............‬ســعودي اجلنســية) (فــرزت أوراق مســتقلة‬\n‫للقبــض عليهمــا) بعــد تواطــؤ اخلفيــر املكلــف بحراســة الوســائط‬\n\n                                                                                         ‫‪332‬‬\n\f      ‫املدعــى عليــه املذكــور (فــرزت لــه أوراق مســتقلة ملــا يتعلــق بخيانــة‬\n      ‫األمانــة ونكــث القســم) وباســتجواب املدعــى عليــه أقــر بأنــه اتفــق مــع‬\n      ‫‪ .............‬بــأن ميكنــه مــن ســرقة ماكينــة بحريــة مــن مكائــن قطــاع‬\n      ‫حــرس احلــدود مبقابــل مبلــغ خمســة آالف ريــال وذكــر بــأن ‪.............‬‬\n      ‫قــام بســرقة املكينــة ومعــه أ‪ .............‬وصــادق علــى أقوالــه بذلــك شــرع ًا‬\n      ‫وقــد أســفر التحقيــق مــع املدعــى عليــه باتهامــه بتمكــن املتهــم ‪.............‬‬\n      ‫مــن ســرقة ماكينــة الواســطة البحريــة رقــم (‪ ).............‬التابعــة لقطــاع‬\n      ‫حــرس احلــدود مبحافظــة فرســان مقابــل مبلغـ ًا قــدره خمســة آالف ريــال‬\n      ‫وبالبحــث عــن ســوابقه لــم يعثــر لــه علــى ســوابق مســجلة وحيــث أن مــا‬\n      ‫أقــدم عليــه املدعــى عليــه فعــل محــرم ومعاقــب عليــه شــرع ًا لــذا أطلــب‬\n      ‫إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة لقــاء ذلــك وبســؤال‬\n      ‫ا مــا ذكــره‬     ‫املدعــى عليــه عمــا جــاء بدعــوى املدعــي العــام أجــاب قائ ـ ً‬\n      ‫املدعــي العــام مــن اتهامــي بتمكــن املتهــم ‪ .............‬مــن ســرقة ماكينــة‬\n      ‫الواســطة البحريــة رقــم (‪ ).............‬التابعــة لقطــاع حــرس احلــدود‬\n      ‫مبحافظــة فرســان مقابــل مبلغ ـ ًا قــدره خمســة آالف ريــال فهــذا غيــر‬\n      ‫صحيــح والصحيــح أننــي ال عالقــة لــي أبــد ًا بجرميــة الســرقة التــي حصلت‬\n      ‫ملاكينــة الواســطة البحريــة هكــذا أجــاب ثــم جرى ســؤال املدعــي العام‬\n      ‫ا بينتــي علــى‬    ‫هــل لديــه بينــة علــى دعــواه ضــد املدعــى عليــه فأجــاب قائـ ً‬\n      ‫ذلــك هــي إقــراره املصــدق شــرع ًا مــن محكمــة فرســان املرفــق باملعاملــة‬\n      ‫علــى لفــة رقــم (‪ )11‬والــذي يتضمــن إقــراره بتمكينــه للمتهــم ‪.............‬‬\n      ‫مــن ســرقة مــا كينــة الواســطة البحريــة مقابــل أن يعطيــه مبلغ ـ ًا قــدره‬\n      ‫خمســة آالف ريــال هكــذا أجــاب وبعــرض ذلــك علــى املدعــى عليــه قــال‬\n      ‫صحيــح أننــي أقريــت بذلــك لــدى شــرطة فرســان وصــدق إقــراري شــرع ًا‬\n\n\n‫‪333‬‬\n\f‫ولكــن كان ذلــك بســبب اإلكــراه مــن قبــل شــرطة فرســان وال توجــد‬\n‫لــدي بينــة علــى اإلكــراه هكــذا أجــاب وبعــد ســماع الدعــوى واإلجابــة‬\n‫جــرى منــي دراســة األوراق واالطــاع علــى محضــر القبــض املرفــق‬\n‫باملعاملــة فوجدتــه يتضمــن القبــض علــى املدعــى عليــه بعــد اعترافــه‬\n‫بتمكــن املتهــم املذكــور أعــاه بســرقة ماكينــة الواســطة البحريــة‬\n‫رقــم (‪ ).............‬التابعــة لقطــاع حــرس احلــدود ثــم جــرى االطــاع علــى‬\n‫اإلقــرار الــذي ذكــره املدعــي العــام واملرفــق باملعاملــة علــى لفــة رقــم‬\n‫(‪ )11‬فوجدتــه يتضمــن إقــرار املدعــى عليــه بتمكينــه للمتهــم ‪.............‬‬\n‫مــن ســرقة ماكينــة الواســطة البحريــة مقابــل مبلغـ ًا قــدره خمســة آالف‬\n‫ريــال ووجــدت أن هــذا اإلقــرار مصــادق عليــه شــرع ًا مــن قبــل فضيلــة‬\n‫قاضــي احملكمــة العامــة مبحافظــة فرســان ثــم جــرى االطــاع علــى‬\n‫صحيفــة ســوابق املدعــى عليــه فوجــدت أنــه ال توجــد ســوابق مســجلة‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث أنكــر املدعــى‬  ‫عليــه فبنـ ً‬\n‫عليــه قيامــه بتمكــن املتهــم ‪ ......‬مــن ســرقة ماكينــة الواســطة البحريــة‬\n‫مقابــل مبلغ ـ ًا قــدره خمســة آالف ريــال وحيــث أن بينــة املدعــي العــام‬\n‫موصلــة علــى كــون املدعــى عليــه قــد قــام بتمكــن املتهــم ‪ .............‬مــن‬\n‫ســرقة الواســطة البحريــة وذلــك إلقــراره بذلــك ولكــون اإلقــرار مصادق‬\n‫عليــه شــرع ًا مــن قبــل فضيلــة قاضــي فرســان وملــا قــرره الفقهــاء رحمهــم‬\n‫اهلل مــن أنــه ال عــذر ملــن أقــر وكذلــك لكــون املدعــى عليــه ال ميلــك‬\n‫بينــة علــى اإلكــراه وألنــه كان بإمكانــه النكــول عــن اإلقــرار أمــام‬\n‫فضيلــة قاضــي محكمــة فرســان ولــم يفعــل وحيــث أن املدعــى عليــه‬\n‫مســتحق لعقوبــة تعزيريــة رادعــة وذلــك خليانتــه األمانــة وغشــه ملرجعــه‬\n‫وتفريطــه بأمــاك الدولــة ومتكينــه للمجرمــن مــن ســرقتها والعبــث‬\n\n\n                                                                                       ‫‪334‬‬\n\f      ‫بهــا والرســول صلــى اهلل عليــه وســلم يقــول (( مــن غشــنا فليــس منــا ))‬\n      ‫وحيــث ال توجــد ســوابق مســجلة عليــه ولــكل مــا تقــدم ف ــقد ح ــكمت‬\n                                                              ‫مبــا يلــي أو ًال ‪ /‬ثبــت لـ ّ‬\n      ‫ـدي إدانــة املدعــى عليــه بتمكــن املتهــم ‪.............‬‬\n      ‫مــن ســرقة ماكينــة الواســطة البحريــة رقــم (‪ ).............‬التابعــة لقطــاع‬\n      ‫حــرس احلــدود مبحافظــة فرســان مقابــل مبلغـ ًا قــدره خمســة آالف ريــال ‪.‬‬\n      ‫ثانيـ ًا ‪ /‬حكمــت عليــه بالســجن ملــدة ســنة ونصــف تبــدأ مــن تاريخ دخوله‬\n      ‫الســجن علــى ذمــة هــذه القضيــة ويســقط عــن املدعــى عليــه ثالثــة أشــهر‬\n      ‫مــن محكوميتــه وذلــك عنــد حفظــه لســورة الكهــف حفظـ ًا متقنـ ًا بعــد‬\n      ‫اختبــار يجــرى لــه مــن قبــل اجلهــة املختصــة ‪ .‬ثالث ـ ًا ‪ /‬حكمــت بجلــده‬\n      ‫مائــة وخمســون جلــدة مفرقــة علــى دفعــات كل دفعــة خمســون جلــدة‬\n      ‫بــن كل دفعــة واألخــرى مــدة ال تقــل عــن خمســة عشــر يومـ ًا ‪ ،‬وبعــرض‬\n      ‫احلكــم علــى املدعــى عل ــيه قــرر االعتــراض علــى احلكــم مــع تقــدمي‬\n      ‫الئحــة إعتراضيــة عليــه جــرى إفهامــه بــأن عليــه احلضــور بعــد ثالثــة أيــام‬\n      ‫وذلــك الســتالم نســخة مــن احلكــم الشــرعي لالعتــراض عليــه يف مــدة‬\n      ‫قدرهــا ثالثــون يومـ ًا تبــدأ مــن تاريــخ إســتالمه لنســخة احلكــم الشــرعي‬\n      ‫كمــا قــرر املدعــي العــام عــدم االعتــراض علــى احلكــم وقــد جــرى‬\n      ‫النطــق باحلكــم يف الســاعة احلاديــة عشــرة والنصــف صباح ـ ًا بتاريــخ‬\n      ‫‪1434/06/13‬ه ـ وصلــى اهلل علــى س ــيدنا محمــد وآلــه وصحبــه وســلم‪.‬‬\n      ‫قــرار تصديــق رقــم ‪ 34290461‬وتاريــخ ‪1434/08/07‬ه ـ احلمــد هلل‬\n      ‫وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فقــد اطلعنــا نحــن‬\n      ‫قضــاة الدائــرة الرابعــة لتدقيــق القضايــا اجلزائيــة مبحكمــة االســتئناف‬\n      ‫مبنطقــة عســير علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بجــازان برقــم ‪ 341067201‬وتاريــخ ‪1434/07/12‬ه ـ املرفــق‬\n\n\n‫‪335‬‬\n\f‫بهــا القــرار الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪.............‬‬\n‫برقــم ‪ 34240590‬وتاريــخ ‪1434/06/13‬ه ـ اخلــاص بدعــوى املدعــي‬\n‫العــام ضــد ‪ ............. /‬يف قضيــة خيانــة أمانــة علــى الصفــة املوضحــة يف‬\n‫القــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدراســة‬\n‫القــرار وصــورة ضبطــه وأوراق املعاملــة تقــررت املوافقــة علــى احلكــم‬\n‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n‫قاضــي اســتئناف ‪ .............‬ختمــه وتوقيعــه قاضــي اســتئناف ‪.............‬‬\n‫ختمــه وتوقيعــه رئيــس الدائــرة ‪ .............‬ختمــه وتوقيعــه حــرر يف‬\n                                                            ‫‪1434/09/06‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                    ‫‪336‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":331,"source_page_end":336,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"788b70f1393d34ac44f3b7c814bce810d57578758e7ac5e334ac2a2b6a9742c4","normalized_text_hash":"2703244e2cbefe50a01c7eb9cfd0882a4a3986c629b2ab9da351a2eea3f0e883","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p331-34240590"},{"id":"c0efdafb-3770-5e73-8cb1-1b977d72f161","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة مال من حرز بقصد استيفاء حق -من سرق الستيفاء حقه ال تقطع يده (يدرأ عنه حد السرقة) -ثبوت ارتكاب السرقة مبوجب إقرار -درء حد السرقة بالشبهة -رد دعوى املدعي العام -تعزير بالسجن واجللد.","document_number":"34321237","case_number":"34211011","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بجدة ومبشاركة القاضي بالمحكمة العامة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/9/16","year":"1434","subject":"سرقة -سرقة مال من حرز بقصد استيفاء حق -من سرق الستيفاء حقه ال تقطع يده (يدرأ عنه حد السرقة) -ثبوت ارتكاب السرقة مبوجب إقرار -درء حد السرقة بالشبهة -رد دعوى املدعي العام -تعزير بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك ‪ 34321237 :‬تاريخه‪1434/9/16 :‬هـ‬\n                           ‫رقم الدعوى‪34211011:‬‬\n            ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34383415‬تاريخه‪1434/12/22 :‬هـ‬\n\n\n\n      ‫ســرقة ‪ -‬ســرقة مــال مــن حــرز بقصــد اســتيفاء حــق ‪ -‬مــن ســرق‬\n      ‫الســتيفاء حقــه ال تقطــع يــده (يــدرأ عنــه حــد الســرقة) ‪ -‬ثبــوت ارتــكاب‬\n      ‫الســرقة مبوجــب إقــرار ‪ -‬درء حــد الســرقة بالشــبهة ‪ -‬رد دعــوى املدعــي‬\n                                               ‫العــام ‪ -‬تعزيــر بالســجن واجللــد‪.‬‬\n\n\n\n\n      ‫قــال ابــن قدامــة رحمــه اهلل يف املغنــي ‪(:‬وإن عجــز عــن اســتيفاء دينــه‪،‬‬\n      ‫أو أرش جنايتــه‪ ،‬فســرق قــدر دينــه‪ ،‬أو حقــه‪ ،‬فــا قطــع عليــه‪ .‬وقــال‬\n      ‫القاضــي‪ :‬عليــه القطــع‪ ،‬بنــاء علــى أصلنــا يف أنــه ليــس لــه أخــذ قــدر‬\n      ‫دينــه‪ .‬ولنــا أن هــذا مختلــف يف حلــه‪ ،‬فلــم يجــب احلــد بــه‪ ،‬كمــا لــو‬\n      ‫وطــئ يف نــكاح مختلــف يف صحتــه‪ ،‬وحتــرمي األخــذ ال مينــع الشــبهة‬\n                        ‫الناشــئة عــن االختــاف‪ ،‬واحلــدود تــدرأ بالشــبهات)‪.‬‬\n\n\n\n\n‫‪337‬‬\n\f‫اتهــام املدعــي العــام للمدعــى عليــه بقيامــه بســرقة (‪)18342‬ثمانيــة‬\n‫عشــر ألفـ ًا وثالثمائــة واثنــان وأربعــون ريــا ًال و(كاميــرا والب تــوب) و(‪)4‬‬\n‫أربــع مقصــات خاصــة بالزراعــة تقــدر قيمتهــا ب(‪ )2800‬ألفــان وثمامنئــة‬\n‫ريــال مــن داخــل محــل ‪ ....‬بعــد كســر بــاب احملــل وكســر درج احملاســبة‬\n‫وســرقة ســيارة نــوع (‪ )........‬حتمــل اللوحــة رقــم(‪ )......‬يطلــب إثبــات مــا‬\n‫أســند إليــه واحلكــم عليــه بحــد الســرقة‪ .‬حيــث إنــه أبلــغ مركــز شــرطة‬\n‫‪ .......‬الوكيــل الشــرعي لشــركة ‪ ...‬املواطــن‪ ...../‬عــن تعــرض محــل‪......‬‬\n‫التابــع للشــركة لســرقة مبلــغ(‪ )18342‬ثمانيــة عشــر ألف ـ ًا وثالثمئــة‬\n‫واثنــان وأربعــن ريــا ًال و(كاميــرا والب تــوب) و(‪)4‬أربــع مقصــات خاصــة‬\n‫بالزراعــة تقــدر قيمتهــا إجمــاال بــ(‪ )2800‬ألفــان وثمامنائــة ريــال‪ .‬أبلــغ‬\n‫ذات املواطــن عــن ســرقة ســيارة (‪ )......‬حتمــل لوحــة لرقــم(‪ )...‬مدعيـ ًا أن‬\n‫ال علــى قــرص مدمــج‬    ‫املدعــى عليــه ســرق جميــع مــا ذكــر‪ .‬وقــدم تســجي ً‬\n‫يظهــر فيــه املدعــى عليــه يكســر درج احملاســبة ويســرق منــه ثــم يضــع‬\n‫يــده داخــل جيبــه ‪ .‬وباالنتقــال ومعاينــة املوقــع تبــن فــزر أحــد مداخلــه‬\n‫الثالثــة ‪ .‬وبتاريــخ ‪....‬مت القبــض علــى املدعــى عليــه بداخــل مســكن‬\n‫بحــي ‪ .......‬وبرفقتــه عــدة أشــخاص مــن ضمنهــم نســاء كمــا مت ضبــط‬\n‫الســيارة املســروقة‪ ،‬أقــر املدعــى عليــه مبــا جــاء يف الدعــوى وأن الســبب‬\n‫أنــه يعمــل لديــه ولــم يعطــه رواتبــه وقدرهــا تســعة آالف ريــال وأحضــر‬\n‫بينــة علــى ذلــك وأن املســروق مبلــغ وقــدره ســتة آالف وثمامنائــة ريــال‬\n‫وليــس ثمانيــة عشــر ألــف وال بينــة للمدعــي العــام علــى ذلــك‪ ،‬فبنــاء علــى‬\n‫مــا تقــدم ومبــا أن صاحــب احلــق اخلــاص أقــر بأنــه لــم يســلم املدعــى عليــه‬\n\n                                                                                       ‫‪338‬‬\n\f      ‫راتــب شــهر ســبتمبر ونصــف أكتوبــر ومبــا أن مجمــوع هاذيــن الراتبــن‬\n      ‫يســاوي تقريبا مبلغا وقدره تســعة آالف ريال ومجموع ما ســرقه املدعي‬\n      ‫يبلــغ ســتة آالف وثمامنائــة ريــال ومبــا أن ذلــك يعــد شــبهة يــدرأ بهــا احلــد‬\n      ‫وهــذا الفعــل موجــب لتعزيــر املدعــى عليــه ومبــا أن وضــع مفتــاح الســيارة‬\n      ‫علــى الكاشــير ال يعــد حــرزا ملفتــاح الســيارة ولكــن أخــذ املدعــى عليــه‬\n                                     ‫للمفتــاح واســتعماله للســيارة موجــب لتعزيــره ‪.‬‬\n                                                                     ‫حكمت احملكمة‪:‬‬\n             ‫أوال‪ :‬رد دعوى املدعي العام بإقامة حد السرقة على املدعى عليه ‪.‬‬\n      ‫ثانيــا‪ :‬بســجنه عامــن مــن تاريــخ توقيفــه وجلــده مائتــي جلــدة مفرقــة‬\n      ‫علــى دفعــات كل دفعــة خمســون جلــدة بــن كل دفعــة وأخــرى مــا ال‬\n                                                                    ‫يقــل عــن عشــرة أيــام‬\n      ‫ثالثــا ‪ :‬إبعــاده عــن اململكــة بعــد تنفيــذ العقوبــة‪ ،‬قــرر املدعــي العــام‬\n      ‫االعتــراض وطلــب االســتئناف بالئحــة وقــرر املدعــى عليــه القناعــة‪،‬‬\n                                         ‫صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬القاضــي باحملكمــة العامــة بجــدة‬\n      ‫ومبشــاركة القاضي باحملكمة العامة ‪ ....‬والقاضي باحملكمة العامة‬\n      ‫بجــدة ‪ ...‬خلــف الشــيخ ‪ ...‬وبنــاء علــى املعاملــة احملالــة إلينــا مــن رئيــس‬\n      ‫احملكمــة برقــم ‪ 34211011‬يف ‪1434/05/07‬ه ـ واملقيــدة باحملكمــة‬\n      ‫برقــم ‪ 341122381‬يف ‪1434/05/07‬ه ـ ويف هــذا اليــوم األربعــاء‬\n      ‫‪ 1434/5/15‬افتتحــت اجللســة الســاعة ‪ 09 : 30‬وفيهــا حضــر املدعــي‬\n      ‫العــام ‪ ...‬وادعــى علــى احلاضــر معــه ‪ )31( ...‬عام ـ ًا ‪ ،‬فلبينــي اجلنســية‬\n\n‫‪339‬‬\n\f‫مبوجــب رخصــة اإلقامــة رقــم (‪ )...‬ســائق خاص بتاريــخ ‪1433/12/21‬هـ‬\n‫أبلغ مركز شــرطة الشــرفية الوكيل الشــرعي لشــركة ‪...‬املواطن‪.../‬‬\n‫عــن تعــرض محــل ‪ .......‬التابــع للشــركة لســرقة مبلــغ(‪ )18342‬ثمانيــة‬\n‫عشــر ألــف وثالثمئــة واثنــان وأربعــن ريــا ًال و(كاميــرا والب تــوب) و(‪)4‬‬\n‫أربــع مقصــات خاصــة بالزراعــة تقــدر قيمتهــا إجمــاال بـ(‪)2800‬ألفــان‬\n‫وثمامنائــة ريــال‪ .‬وبتاريــخ ‪1433/12/29‬ه ـ أبلــغ ذات املواطــن عــن ســرقة‬\n‫ســيارة (‪ )........‬حتمــل لوحــة لرقــم(‪ ).... ...‬مدعيـ ًا أن املدعــى عليــه ســرق‬\n‫ال علــى قــرص مدمــج يظهــر فيــه املدعــى‬   ‫جميــع مــا ذكــر‪ .‬وقــدم تســجي ً‬\n‫عليــه يكســر درج احملاســبة ويســرق منــه ثــم يضــع يــده داخــل جيبــه ‪.‬‬\n‫وباالنتقــال ومعاينــة املوقــع تبــن فــزر أحــد مداخلــه الثالثــة ‪ .‬وبتاريــخ‬\n‫‪1434/1/9‬ه ـ مت القبــض علــى املدعــى عليــه بداخــل مســكن بحــي‬\n‫الفيصليــة وبرفقتــه عــدة أشــخاص مــن ضمنهــم نســاء (مت فــرز أوراق‬\n‫لهــم و ُأحيلــوا إلــى دائــرة التحقيــق يف قضايــا االعتــداء علــى العــرض‬\n‫واألخــاق مبوجــب اخلطــاب رقــم ‪ 11/472‬وتاريــخ ‪1434/1/9‬ه ـ‬\n‫لعــدم صلتهــم بواقعــة الســرقة) كمــا مت ضبــط الســيارة املســروقة‪.‬‬\n‫بســماع أقــوال املدعــي‪ /‬أفــاد أن املدعــى عليــه املذكــور ســرق مبلــغ‬\n‫(‪ )18342‬ثمانيــة عشــر الــف وثالثمئــة واثنــان وأربعــن ريــا ًال و(كاميــرا‬\n‫وآلب تــوب) و(‪ )4‬أربــع مقصــات خاصــة بالزراعــة تقــدر قيمتهــا إجمــا ًال‬\n‫ب(‪ )2800‬ألفــان وثمامنائــة ريــال وســرق ســيارة نــوع ‪ .....‬حتمــل لوحــة‬\n‫لرقــم (‪ )... ....‬وقــدم تســجيل علــى (قــرص مدمــج) يوضــح فيــه ســرقة‬\n‫املدعــى عليــه للمحــل ‪ .‬بســماع شــهادة‪ .../‬فلبينــي اجلنســية أفــاد أن‬\n‫الســيارة املســروقة واملضبوطــة بحوزتــه ســبق أن أحضرهــا لــه املدعــى‬\n‫عليــه قبــل أســبوع مــن تاريــخ القبــض عليــه باســتجواب املدعــى عليــه‪.../‬‬\n\n\n                                                                                      ‫‪340‬‬\n\f      ‫أقــر بفتــح محــل ‪ .......‬وســرقة جهــاز (‪ ).......‬و(‪)4‬أربــع مقصــات زراعيــة‬\n      ‫و(كاميــرا) وأنــه بتاريخ‪1433/12/24‬ه ـ كســر بــاب احملــل اخللفــي‬\n      ‫وكســر درج احملاســبة وســرق منــه (‪ )2000‬ألفــي ريــال كمــا ســرق‬\n      ‫بتاريــخ ‪1433/12/28‬ه ـ فــرع آخــر للشــركة حيــث دخــل إليــه وســرق‬\n      ‫مبلــغ(‪ )2000‬ألفــي ريــال أيض ـ ًا وأنكــر ســرقة الســيارة وذكــر أنهــا‬\n      ‫ســلمت لــه ‪ .‬ومبواجهتــه باملدعــي أصــر كل منهمــا علــى أقوالــه ‪ ،‬كمــا‬\n      ‫ذكــر املدعــي أن املدعــى عليــه لــم يســبق لــه تســلم هذه الســيارة ‪ .‬وقد مت‬\n      ‫تســليم الســيارة إلــى صاحبهــا مبوجــب اإلقــرار املــدون ص(‪)12‬لفــة(‪.)35‬‬\n      ‫كمــا مت فــرز صــورة مــن أوراق القضيــة بشــأن املدعــى عليــه وكفيلــه‬\n      ‫ومــن مكنــه مــن العمــل إلحالتهــا إلــى جهــة االختصــاص كونــه ال يعمــل‬\n      ‫لــدى كفيلــه‪ .‬وانتهــى التحقيــق إلــى توجيــه االتهــام للمدعــى عليــه‪... /‬‬\n      ‫بســرقة (‪)18342‬ثمانيــة عشــر ألــف وثالثمائــة واثنــان وأربعــون ريــا ًال‬\n      ‫و(كاميــرا والب تــوب) و(‪)4‬أربــع مقصــات خاصــة بالزراعــة تقــدر‬\n      ‫قيمتهــا ب(‪)2800‬ألفــان وثمامنائــة ريــال مــن داخــل محــل ‪ .......‬بعــد‬\n      ‫كســر بــاب احملــل وكســر درج احملاســبة وســرقة ســيارة نــوع (‪)......‬‬\n      ‫حتمــل اللوحــة رقــم(‪ ).......‬مبوجــب قــرار االتهــام رقــم (‪ )6/24‬املؤيــد‬\n      ‫مــن قبــل جلنــة إدارة الهيئــة مبوجــب قــرار املراجعــة رقــم (‪/534‬م) لعــام‬\n      ‫‪1434‬ه ـ وذلــك لألدلــة والقرائــن اآلتيــة ‪ -1 :‬مــا جــاء يف إقــراره املصــدق‬\n      ‫شــرع ًا املنــوه عنــه ص (‪ )16-13‬لفــة (‪ -2 .)35‬مــا جــاء يف أقوالــه املدونــة‬\n      ‫علــى ص(‪ )12-7‬لفــة (‪-3 .)35‬مــا جــاء مبحضــر التحريــات والبحــث‬\n      ‫اجلنائــي املتضمــن القبــض عليــه وعلــى الســيارة املســروقة املنــوه عنــه لفــة‬\n      ‫(‪ -4 .)18‬مــا ورد مبحضــر االنتقــال واملعاينــة املنــوه عنــه املرفــق ص(‪)2‬‬\n      ‫لفــة (‪ -5 .)35‬مــا ورد مبحضــر االطــاع علــى تســجيل الســي دي املنــوه‬\n\n\n‫‪341‬‬\n\f                                                          ‫عنــه ص(‪)14‬لفــة(‪. )9‬‬\n‫‪-6‬شهادة ‪ ...‬املدونة على ص (‪ )16-13‬لفة (‪ .)35‬وبالبحث عن سوابقه‬\n‫لــم يعثــر لــه علــى ســوابق مســجلة حتــى تاريخــه ‪ .‬وحيــث إن مــا أقــدم‬\n‫عليــه املدعــى عليــه وهــو بكامــل أهليتــه املعتبــرة شــرع ًا مــن ســرقة مــال‬\n‫محتــرم مــن حــرزه وبالــغ النصــاب وال شــبهة لــه فيــه وطالــب بــه صاحبــه‬\n‫فعــل محــرم ومعاقــب عليــه شــرع ًا أطلــب إثبــات مــا أســند إليــه واحلكــم‬\n‫عليــه بحــد الســرقة الــوارد يف اآليــة الكرميــة رقــم (‪ )38‬مــن ســورة املائدة‬\n‫‪ .‬علمـ ًا بــأن احلــق اخلــاص الزال قائمـاً‪ .‬هــذه دعــواي وبســؤال املدعــى عليــه‬\n‫عمــا جــاء يف الدعــوى بواســطة املترجمــن باحملكمــة ‪ ....‬و ‪ ....‬أجــاب‬\n‫ا إن مــا ذكــره املدعــي العــام يف دعــواه صحيــح إال أن املبلــغ الــذي‬    ‫قائـ ً‬\n‫قمــت بأخــذه أربعــة آالف ريــال فقــط وليــس ثمانيــة عشــر ألــف ريــال‬\n‫ا إننــي أعمــل‬  ‫هكــذا أجــاب وبســؤاله كيــف دخــل احملــل أجــاب قائ ـ ً‬\n‫يف هــذا احملــل وقــد قمــت بالدخــول إلــى هــذا احملــل بعــد إغالقــه يف فتــرة‬\n‫الظهــر وقمــت بفــزر البــاب اخلارجــي الــذي كان مغلقـ ًا بإحــكام وذلــك‬\n‫بواســطة مفــك ثــم ذهبــت إلــى الكاشــير وفتحتهــا بشــكل طبيعــي‬\n‫وقمــت بأخــذ مبلــغ وقــدره ألفــي ريــال ثــم يف املــرة الثانيــة قمــت بفــزر‬\n‫البــاب بواســطة املفــك وذهبــت للكاشــير وأخــذت مبلغ ـ ًا وقــدره ألفــي‬\n‫ريــال وكاميــرا وتابلــت وأربــع مقصــات خاصــة بالزراعــة وكان مفتــاح‬\n‫الســيارة علــى الكاشــير وقمــت بأخــذه وأخــذت الســيارة ملــدة أربعــة أيــام‬\n‫وكان بــن املــرة األولــى والثانيــة للســرقة قرابــة أســبوع هكــذا أجــاب‬\n‫ا إننــي أعمــل يف‬    ‫وبســؤاله عــن الدافــع الــذي دفعــه للســرقة أجــاب قائ ـ ً‬\n‫نفــس احملــل وصاحــب احملــل لــم يعطنــي راتبــي ملــدة شــهرين وراتبــي هــو‬\n‫ســتة آالف ريــال شــهري ًا وأنــا كنــت محتاج ـ ًا للمــال ألن والــدي مريــض‬\n\n\n                                                                                       ‫‪342‬‬\n\f      ‫وبحاجــة لعمليــة لــذا أخــذت املبلــغ هكــذا أجــاب ثــم ذكــر املدعــى عليــه‬\n      ‫ا إننــي ال أعلــم أن عقوبــة الســارق القطــع ألننــي غيــر مســلم وأنــا‬       ‫قائ ـ ً‬\n      ‫مســيحي هكــذا قــال وبســؤال املدعــي البينــة علــى دعــواه قــال أطلــب‬\n      ‫اإلمهــال إلحضارهــا يف اجللســة القادمــة وعليــه تأجلــت اجللســة ثــم يف‬\n      ‫جلســة أخــرى حضــر املدعــي العــام ‪ ...‬كمــا حضــر املدعى عليه وبســؤال‬\n      ‫ا أطلــب‬    ‫املدعــي العــام عــن البينــة التــي وعــد بإحضارهــا أجــاب قائ ـ ً‬\n      ‫اإلمهــال إلحضارهــا يف اجللســة القادمــة وعليــه جــرى تأجيــل اجللســة ثــم‬\n      ‫يف جلســة أخــرى حضــر املدعــي العــام كمــا حضــر املدعــى عليــه ‪...‬‬\n      ‫وبســؤال املدعــي العــام عــن البينــة قــال إنــه مت طلبهــم ثــاث مــرات ولــم‬\n      ‫يحضــروا وأكتفــي مبــا جــاء يف املعاملــة وبســؤال املدعــى عليــه بواســطة‬\n      ‫املترجمــن بهــذه احملكمــة ‪ ....‬و ‪ ....‬علــى بينتــه علــى أنــه لــم يســتلم راتبــه‬\n      ‫ا لــدي بينــة وهــو العامــل الــذي يعمــل معــي‬          ‫ملــدة شــهرين أجــاب قائ ـ ً‬\n      ‫باحملــل واســمه ‪ ...‬ويعمــل مبحــل ‪ ......‬بالــدور األول ويقــع احملــل يف حــي‬\n      ‫ا إنــي‬ ‫‪ .....‬شــارع ‪ ....‬وبســؤاله عــن كيفيــة اســتالمه لراتبــه أجــاب قائ ـ ً‬\n      ‫اســتلم الراتــب وأوقــع إيصــاال باالســتالم وآخــر شــهرين لــم أســتلمها ولــم‬\n      ‫أوقــع باالســتالم هكــذا أجــاب وإلحضــار الشــاهد جــرى تأجيــل اجللســة‬\n      ‫ثــم يف جلســة أخــرى حضــر املدعــي العــام كمــا حضــر املدعــى عليــه‬\n      ‫‪ .......‬كمــا حضــر يف هــذه اجللســة ‪ ...‬ســعودي بالســجل املدنــي رقــم (‪)...‬‬\n      ‫وحيــث إن وكالتــه ال تخولــه يف مراجعــة احملاكــم واملدافعــة واملرافعــة‬\n      ‫واإلقــرار واإلنــكار وجــرى إفهــام الوكيــل بتعديــل وكالتــه جــرى رفــع‬\n      ‫اجللســة ثــم يف جلســة أخــرى حضــر املدعــي العــام ‪ ...‬وحضــر املدعــى‬\n      ‫عليــه ‪ ...‬كمــا حضــر إلينــا املدعــي باحلــق اخلــاص ‪ ...‬ســعودي مبوجــب‬\n      ‫الســجل املدنــي رقــم(‪ )...‬كمــا حضــر املترجــم باحملكمــة ‪ ....‬نيجيــري‬\n\n\n‫‪343‬‬\n\f‫اجلنســية مبوجــب اإلقامــة رقــم (‪ )....‬وهــو مالــك محــل ‪ .......‬والــذي كان‬\n‫يعمــل بــه املدعــى عليــه وبســؤاله عمــا لديــه أفــاد قائــا إن املدعــى عليــه‬\n‫مت التعاقــد معــه يف شــهر ســبتمبر مــن عــام ‪2012‬م علــى راتــب وقــدره‬\n‫ســتة آالف ريــال وقــد اســتلم املدعــى عليــه راتــب شــهر ســبتمبر بتاريــخ‬\n‫‪2012/10/30‬م ثــم داوم املدعــى عليــه إلــى منتصــف شــهر اكتوبــر مــن‬\n‫ذات العــام واختفــى بعــد ذلــك ولــم يســتلم راتبــه لنصــف شــهر اكتوبــر‬\n‫هكــذا قــال وبعــرض ذلــك علــى املدعــى عليــه عــن طريــق املترجــم أجــاب‬\n‫قائــا مــا ذكــره صاحــب احملــل غيــر صحيــح حيــث إنــي لــم أســتلم راتــب‬\n‫شــهر عشــرة هكــذا أجــاب وبعــرض ذلــك علــى املدعــي باحلــق اخلــاص‬\n‫أجــاب قائــا لــدي مــا يثبــت مــا ذكرتــه وهــو مســيرات رواتــب شــهر‬\n‫ســبتمبر مــن عــام ‪2012‬م ومســتعد بإحضــاره يف اجللســة القادمــة وعليــه‬\n‫حضــر املدعــي العــام‬          ‫جــرى تأجيــل اجللســة ثــم يف جلســة أخــرى‬\n‫كمــا حضــر املدعــى عليــه ‪ ....‬كمــا حضــر يف هــذه اجللســة ‪ ...‬ســعودي‬\n‫بالســجل املدنــي رقــم(‪ )....‬بصفتــه وكيــا عــن املدعــي باحلــق اخلــاص‬\n‫‪ ...‬مبوجــب الوكالــة رقــم (‪ )...‬وتاريــخ ‪1433/11/28‬ه ـ والصــادرة مــن‬\n‫كتابــة العــدل الثانيــة يف شــمال محافظــة جــدة كمــا حضــر املترجــم‬\n‫‪ ...‬فلبينــي اجلنســية مبوجــب اإلقامــة رقــم (‪ )....‬وبســؤال وكيــل املدعــي‬\n‫عمــا اســتمهل مــن أجلــه قــدم مســير رواتــب شــهري يوليــو واغســطس مــن‬\n‫عــام ‪2012‬م واملتضمــن أن املدعــى عليــه اســتلم راتــب شــهر يوليــو وقــدره‬\n‫ثالثــة آالف وخمســمائة ريــال وراتــب شــهر اغســطس وقــدره ثالثــة آالف‬\n‫وســتمائة ريــال وبعرضــه علــى املدعــى عليــه عــن طريــق املترجــم أجــاب‬\n‫قائــا إننــي اســتلمت راتــب هذيــن الشــهرين وقــد خصــم مــن راتبــي وهــذا‬\n‫اخلصــم صحيــح لســلفة اســتلفتها مــن صاحــب احملــل وغيابــات غبتهــا‬\n\n\n                                                                                      ‫‪344‬‬\n\f      ‫هكــذا أجــاب وبســؤال وكيــل املدعــي وكالــة عــن مســير رواتــب باقــي‬\n      ‫األشــهر أجــاب قائــا أطلــب املهلــة إلحضــاره يف اجللســة القادمــة هكــذا‬\n      ‫أجــاب وعليــه جــرى تأجيــل اجللســة ثــم يف جلســة أخــرى حضــر املدعــي‬\n      ‫العــام ‪ ...‬وحضــر املدعــى عليــه ‪ .....‬كمــا حضــر إلينــا املدعــي باحلــق‬\n      ‫اخلــاص ‪ ....‬كمــا حضــر املترجــم ‪...‬فلبينــي اجلنســية مبوجــب اإلقامــة‬\n      ‫رقــم (‪ ).....‬واملدونــة هويتــه ســابقا وبســؤال املدعــي باحلــق اخلــاص عمــا‬\n      ‫اســتمهل مــن أجلــه قــدم مســير الرواتــب لشــهر فبرايــر لعــام ‪2012‬م‬\n      ‫واملتضمــن اســتالم املدعــى عليــه مبلغــا وقــدره أربعــة آالف وثالثمائــة‬\n      ‫ريــال ومســير الرواتــب لشــهر مــارس لعــام ‪2012‬م واملتضمــن اســتالم‬\n      ‫املدعــى عليــه مبلغــا وقــدره ألــف ريــال ومســير الرواتــب لشــهر أبريــل‬\n      ‫لعــام ‪2012‬م واملتضمــن اســتالم املدعــى عليــه مبلغــا وقــدره أربعــة االف‬\n      ‫ريــال ومســير الرواتــب لشــهر مايــو لعــام ‪2012‬م واملتضمــن اســتالم‬\n      ‫املدعــى عليــه مبلغــا وقــدره خمســة االف وأربعمائــة وخمســون ريــاال‬\n      ‫ومســير الرواتــب لشــهر يونيــو لعــام ‪2012‬م واملتضمــن اســتالم املدعــى‬\n      ‫عليــه مبلغــا وقــدره ثالثــة االف ريــال وبســؤاله عــن مســير الرواتــب لشــهر‬\n      ‫ســبتمبر ونصــف أكتوبــر أجــاب قائــا ‪ :‬لــم يســتلم املدعــى عليــه راتــب‬\n      ‫هاذيــن الشــهرين هكــذا أجــاب وبعــرض ذلــك علــى املدعــى عليــه عــن‬\n      ‫طريــق املترجــم أجــاب قائــا مــا ذكــره املدعــي باحلــق اخلــاص كلــه‬\n      ‫صحيــح هكــذا أجــاب وللتأمــل جــرى تأجيــل اجللســة ثــم يف جلســة‬\n      ‫أخــرى حضــر املدعــي العــام ‪ ....‬وحضــر املدعــى عليــه ‪ ...‬كمــا حضــر‬\n      ‫املترجــم ‪ ...‬فلبينــي اجلنســية مبوجــب اإلقامــة رقــم (‪ )...‬وبعــد االطــاع‬\n      ‫علــى الدعــوى وتأملهــا عليــه فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n      ‫ومبــا أن املدعــي العــام أقــام بينــة تؤيــد دعــواه علــى قيــام املدعــى عليــه‬\n\n\n‫‪345‬‬\n\f‫بســرقة مــال محتــرم مــن حــرزه وبالــغ النصــاب وهــو مبلــغ وقــدره أربعــة‬\n‫آالف ريــال و(كاميــرا والب تــوب) وأربــع مقصــات خاصــة بالزراعــة‬\n‫تقــدر قيمتهــا بألفــن وثمامنائــة ريــال مــن داخــل محــل ‪.....‬وبينتــه إقــرار‬\n‫املدعــى عليــه بســرقة مبلــغ وقــدره أربعــة آالف ريــال و(كاميــرا والب‬\n‫تــوب) وأربــع مقصــات خاصــة بالزراعــة تقــدر قيمتهــا بألفــن وثمامنائــة‬\n‫ريــال مــن داخــل محل‪.....‬ومبــا أن املدعــي العــام لــم يقــدم بينــة علــى ســرقة‬\n‫املدعــى عليــه مبلغــا وقــدره ثمانيــة عشــر ألــف ريــال ومبــا أن صاحــب احلق‬\n‫اخلــاص أقــر بأنــه لــم يســلم املدعــى عليــه راتــب شــهر ســبتمبر ونصــف‬\n‫أكتوبــر ومبــا أن مجمــوع هاذيــن الراتبــن يســاوي تقريبــا مبلغــا وقــدره‬\n‫تســعة آالف ريــال ومجمــوع مــا ســرقه املدعــي يبلــغ ســتة آالف وثمامنائــة‬\n‫ريــال ومبــا أن ذلــك يعــد شــبهة يــدرأ بهــا احلــد قــال ابــن قدامــة رحمــه اهلل‬\n‫يف املغنــي‪(:‬وإن عجــز عــن اســتيفاء دينــه‪ ،‬أو أرش جنايتــه‪ ،‬فســرق قــدر‬\n‫دينــه‪ ،‬أو حقــه‪ ،‬فــا قطــع عليــه‪ .‬وقــال القاضــي‪ :‬عليــه القطــع‪ ،‬بناء على‬\n‫أصلنــا يف أنــه ليــس لــه أخــذ قــدر دينــه‪ .‬ولنــا أن هــذا مختلــف يف حلــه‪،‬‬\n‫فلــم يجــب احلــد بــه‪ ،‬كمــا لــو وطــئ يف نــكاح مختلــف يف صحتــه‪،‬‬\n‫وحتــرمي األخــذ ال مينــع الشــبهة الناشــئة عــن االختــاف‪ ،‬واحلــدود تــدرأ‬\n‫بالشــبهات)‪.‬وهذا الفعــل موجــب لتعزيــر املدعــى عليــه ومبــا أن وضــع‬\n‫مفتــاح الســيارة علــى الكاشــير ال يعــد حــرزا ملفتــاح الســيارة ولكــن‬\n‫أخــذ املدعــى عليــه للمفتــاح واســتعماله للســيارة موجــب لتعزيــره وجلميــع‬\n‫مــا تقــدم فقــد حكمنــا مبــا يلــي‪ :‬أوال‪ :‬رد دعــوى املدعــي العــام إقامــة‬\n‫حــد الســرقة علــى املدعــى عليــه ‪....‬ثانيــا‪ :‬تعزيــر املدعــى عليــه ‪ ....‬بســجنه‬\n‫عامــن مــن تاريــخ توقيفــه وجلــده مائتــي جلــدة مفرقــة علــى دفعــات كل‬\n‫دفعــة خمســون جلــدة بــن كل دفعــة وأخــرى مــا ال يقــل عــن عشــرة أيــام‬\n\n\n                                                                                          ‫‪346‬‬\n\f      ‫وإبعــاده عــن اململكــة بعــد تنفيــذ العقوبــة احملكــوم بهــا عليــه وال يســمح‬\n      ‫لــه بالعــودة إليهــا فيمــا عــدا مــا تســمح بــه تعليمــات احلــج والعمــرة وذلــك‬\n      ‫لتوجــه التهمــة عليــه بالســرقة‪ .‬وبعرضــه علــى املدعــى عليــه عــن طريــق‬\n      ‫املترجــم قــرر القناعــة وبعرضــه علــى املدعــي العــام قــرر عــدم القناعــة‬\n      ‫فأجيــب لطلبــه وجــرى تســليمه نســخة مــن احلكــم لالعتــراض عليــه‬\n      ‫خــال ثالثــن يومــا تبــدأ مــن تاريــخ إصــدار احلكــم وأنــه إذا انتهــت املــدة‬\n      ‫ولــم يقــدم الئحــة اعتراضيــة ســقط حقــه يف االعتــراض وأغلقــت اجللســة‬\n      ‫الســاعة ‪ 10،30‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                   ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/09/16‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬القاضــي يف احملكمــة العامــة‬\n      ‫مبحافظــة جــدة ومبشــاركة القاضيــن بهــا ‪ ...‬و ‪ ... ....‬ففــي يــوم‬\n      ‫اخلميــس املوافــق‪ 1435/01/18‬ه ـ افتتحــت اجللســة الســاعة ‪09،15‬‬\n      ‫وقــد عــادت املعاملــة مــن محكمــة االســتئناف مبنطقــة مكــة املكرمــة‬\n      ‫رفــق خطــاب فضيلــة رئيســها رقــم ‪ 341122381‬يف ‪1435/01/01‬ه ـ‬\n      ‫وبرفقهــا القــرار رقــم ‪ 34383415‬يف ‪1434/12/22‬ه ـ وهــذا نصــه ‪:‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ :‬فقــد‬\n      ‫جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة اخلماســية الثانيــة مبحكمــة‬\n      ‫االســتئناف مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة العامــة بجــدة برقــم ‪ 341122381‬املرفــق‬\n      ‫بهــا الصــك رقــم ‪ 343211237‬وتاريــخ ‪1434/09/16‬ه ـ الصــادر مــن‬\n      ‫أصحــاب الفضيلــة القضــاة باحملكمــة العامــة بجــدة الشــيخ ‪ ...‬والشــيخ‬\n      ‫‪ ...‬والشــيخ ‪ ....‬املتضمــن دعــوى املدعــي العــام ضــد ‪ ... /‬اجلنســية املتهــم‬\n      ‫يف ســرقة احملكــوم فيــه مبــا دون باطنــه وبدراســة احلكــم وصــورة‬\n\n\n‫‪347‬‬\n\f‫ضبطــه والئحتــه االعتراضيــة تقــرر باألكثريــة املوافقــة علــى احلكــم‬\n‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n‫‪ .‬قاضــي اســتئناف ‪ ( ... :‬لــي وجهــة نظــر ) ‪ /‬قاضــي اســتئناف ‪ :‬د‪..‬‬\n‫‪ (..‬لــي وجهــة نظــر ) ‪ /‬قاضــي اســتئناف ‪ / ... :‬قاضــي اســتئناف ‪:‬‬\n‫‪ / ...‬رئيــس اســتئناف‪.... :‬أ‪.‬ه ـ لــذا رأى اثباتــه واغلقــت اجللســة الســاعة‬\n‫‪09،45‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر‬\n                                                        ‫يف ‪ 1435/01/18‬ه ـ‬\n\n\n\n\n                                                                                  ‫‪348‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":337,"source_page_end":348,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"dd3d1126a8eb44624240bddf77656cdfa01595e9f830cd4faa8e94b723cf9fe7","normalized_text_hash":"301c418b4c58c2c2e84f2987b067c0b4bbdbb7e1a368cf1d90b22dd5ad7910c6","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p337-34321237"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

